                                     VoiceGrid(
                                         voices = voices,
                                         selected = when (assignMode) {
                                             1 -> voiceFemale
                                             2 -> voiceMale
                                             else -> selectedVoice
                                         },
                                         onSelect = { key ->
                                             when (assignMode) {
                                                 1 -> voiceFemale = key
                                                 2 -> voiceMale = key
                                                 else -> selectedVoice = key
                                             }
                                         },
                                         modifier = Modifier
                                             .heightIn(max = 320.dp)
                                             .verticalScroll(rememberScrollState()),
                                     )
                                 }
                             }
