/**
 * Вкладка «AI»: один слой — токен и запуск. После запуска в этой же вкладке
 * открывается сайт-хаб npm-hub (дашборд / терминал / файлы / git / инструменты)
 * с GitHub-ранера, где живут CLI-агенты. Агент НЕ форсится при запуске —
 * пользователь сам выбирает и устанавливает его внутри хаба (как в оригинале).
 */
data object AiChatTab : Tab {

    override val options: TabOptions
        @Composable
        get() = TabOptions(
            index = 9u,
            title = "AI",
            icon = rememberVectorPainter(Icons.Outlined.SmartToy),
        )

    // Запуск переживает уход со вкладки и сворачивание приложения
    private val chatScope = kotlinx.coroutines.CoroutineScope(
        kotlinx.coroutines.SupervisorJob() + Dispatchers.IO,
    )
    private val hubStatusFlow = MutableStateFlow("")
    private val hubStartingFlow = MutableStateFlow(false)
    // Fix 5: активная сессия живёт на уровне ОБЪЕКТА, а не в remember —
    // при переключении вкладки (и обратно) WebView не «теряется».
    private val hubSessionFlow = MutableStateFlow<RunnerLlm.Session?>(null)

    private fun rememberSession(s: RunnerLlm.Session) {
        hubSessionFlow.value = s
    }

    @Composable
    override fun Content() {
        val context = LocalContext.current
        val prefs = remember { Injekt.get<OcrPreferences>() }
        val pat by prefs.githubPat().changes().collectAsState(initial = prefs.githubPat().get())
        val starting by hubStartingFlow.collectAsState()
        val status by hubStatusFlow.collectAsState()
        val session by hubSessionFlow.collectAsState()
        var sessions by remember {
            mutableStateOf(runCatching { RunnerLlm.listSessions(context) }.getOrDefault(emptyList()))
        }
        // Лента событий ранера: последние прогоны и пошаговая лента задач.
        // Читатель просил видеть, что ранер делал, не выспрашивая агента.
        var events by remember { mutableStateOf<List<AiGithub.Run>>(emptyList()) }
        var eventsLoading by remember { mutableStateOf(false) }
        var eventsError by remember { mutableStateOf("") }

        val loadEvents: () -> Unit = {
            if (pat.isBlank()) {
                eventsError = "Сначала вставьте GitHub PAT"
            } else {
                eventsLoading = true
                eventsError = ""
                val token = pat.trim()
                chatScope.launch {
                    val got = runCatching { AiGithub.runs(token, AiGithub.DEFAULT_REPO, perPage = 8) }
                        .getOrElse { emptyList() }
                    withContext(Dispatchers.Main) {
                        events = got
                        eventsLoading = false
                        if (got.isEmpty() && eventsError.isBlank()) {
                            eventsError = "Прогонов не найдено или сеть недоступна"
                        }
                    }
                }
            }
        }

        val openSession = session
        if (openSession != null) {
            HubWebView(
                session = openSession,
                onClose = { hubSessionFlow.value = null },
            )
        } else {
            Column(
                modifier = Modifier
                    .fillMaxSize()
                    .statusBarsPadding()
                    .imePadding()
                    .verticalScroll(rememberScrollState())
                    .padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(12.dp),
            ) {
                Text("OpenCode-агент", style = MaterialTheme.typography.titleMedium)
                Text(
                    "Запускает сайт-хаб (npm-hub) на GitHub-ранере: дашборд, терминал, " +
                        "файлы, git, инструменты. Нужного CLI-агента (opencode, DeepSeek, UTIM, " +
                        "AI Shell и др.) вы сами выбираете и устанавливаете прямо внутри хаба. " +
                        "Ранер работает вашим PAT аккаунта, поэтому видит и меняет ВСЕ репозитории " +
                        "аккаунта. Нужен PAT с правом actions:write.",
                    style = MaterialTheme.typography.bodySmall,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                OutlinedTextField(
                    value = pat,
                    onValueChange = { token ->
                        // Пробелы по краям ломают GitHub Auth: token = " ghp_…x "
                    // считается невалидным и старт сессии падает с 401.
                        prefs.githubPat().set(token.trim())
                    },
                    label = { Text("GitHub PAT") },
                    modifier = Modifier.fillMaxWidth(),
                    maxLines = 1,
                )
                var elapsed by remember { mutableStateOf(0L) }
                LaunchedEffect(starting) {
                    elapsed = 0
                    while (starting) {
                        delay(1000)
                        elapsed++
                    }
                }
                FilledTonalButton(
                    enabled = !starting && pat.isNotBlank(),
                    onClick = {
                        val trimmed = pat.trim()
                        val looksLikePat = trimmed.startsWith("ghp_") ||
                            trimmed.startsWith("github_pat_") ||
                            trimmed.startsWith("gho_") ||
                            trimmed.startsWith("ghs_") ||
                            trimmed.startsWith("ghr_")
                        if (!looksLikePat) {
                            hubStatusFlow.value =
                                "❌ Токен не похож на GitHub PAT. Нужен токен, " +
                                "начинающийся на ghp_ / github_pat_ / gho_ (Settings → Developer settings → " +
                                "Personal access tokens). Вставлен Discord- или другой токен?"
                            return@FilledTonalButton
                        }
                        hubStartingFlow.value = true
                        hubStatusFlow.value = "⏳ Запуск хаба npm-hub…"
                        val appCtx = context.applicationContext
                        chatScope.launch {
                            val s = runCatching {
                                RunnerLlm.startOpenCode(
                                    appCtx,
                                    { st -> hubStatusFlow.value = st },
                                    os = "linux",
                                    ui = "mobile",
                                )
                            }.getOrElse {
                                hubStatusFlow.value = "❌ Ошибка запуска: ${it.message ?: it}"
                                null
                            }
                            withContext(Dispatchers.Main) {
                                hubStartingFlow.value = false
                                if (s != null) {
                                    sessions = runCatching { RunnerLlm.listSessions(context) }
                                        .getOrDefault(emptyList())
                                    rememberSession(s)
                                }
                            }
                        }
                    },
                ) { Text(if (starting) "Запускаем…" else "▶ Запустить") }
                if (status.isNotBlank()) {
                    Text(
                        if (starting) "$status • ${elapsed / 60}:${"%02d".format(elapsed % 60)}"
                        else status,
                        style = MaterialTheme.typography.bodySmall,
                    )
                }
                // Лента событий ранера. Раньше читатель видел только «сессии»
                // и кнопку «Открыть»: что ранер делал внутри прогона, не было
                // видно нигде, хотя GitHub Actions это знает.
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    FilterChip(
                        selected = events.isNotEmpty(),
                        onClick = { loadEvents() },
                        label = { Text("События ранера") },
                    )
                    if (eventsLoading) {
                        Text("Загрузка…", style = MaterialTheme.typography.labelSmall)
                    }
                }
                if (eventsError.isNotBlank()) {
                    Text(
                        eventsError,
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
                events.forEach { r ->
                    var steps by remember(r.id) { mutableStateOf<String?>(null) }
                    var stepsLoading by remember(r.id) { mutableStateOf(false) }
                    Column(modifier = Modifier.fillMaxWidth().padding(vertical = 2.dp)) {
                        Text(
                            "#${r.id} ${r.name} — ${r.stateRu}",
                            style = MaterialTheme.typography.bodySmall,
                        )
                        Text(
                            "Показать шаги",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.primary,
                            modifier = Modifier.clickable {
                                if (steps != null || stepsLoading) return@clickable
                                stepsLoading = true
                                val token = pat.trim()
                                val runId = r.id
                                chatScope.launch {
                                    val text = runCatching {
                                        AiGithub.renderJobs(AiGithub.jobs(token, runId))
                                    }.getOrElse { "Не удалось прочитать шаги: ${it.message}" }
                                    withContext(Dispatchers.Main) {
                                        steps = text
                                        stepsLoading = false
                                    }
                                }
                            },
                        )
                        if (stepsLoading) {
                            Text("…", style = MaterialTheme.typography.labelSmall)
                        }
                        steps?.let { txt ->
                            Text(
                                txt,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                            )
                        }
                    }
                }
                if (sessions.isNotEmpty()) {
                    Text("Сессии:", style = MaterialTheme.typography.bodySmall)
                    sessions.forEach { s ->
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp),
                        ) {
                            Text(
                                "${s.model} • ${s.messages.size} сообщ. • ${s.os}",
                                style = MaterialTheme.typography.bodySmall,
                                modifier = Modifier.weight(1f),
                            )
                            if (s.terminalUrl != null || s.url != null) {
                                FilterChip(
                                    selected = false,
                                    onClick = { rememberSession(s) },
                                    label = { Text("Открыть") },
                                )
                            }
                            FilterChip(
                                selected = false,
                                onClick = {
                                    runCatching {
                                        RunnerLlm.deleteSession(context, s)
                                        sessions = RunnerLlm.listSessions(context)
                                    }
                                },
                                label = { Text("✕") },
                            )
                        }
                    }
                }
            }
        }
    }

    /** Сайт-хаб npm-hub в той же вкладке: loading-экран вместо чёрного + ошибки. */
    @Composable
    @android.annotation.SuppressLint("SetJavaScriptEnabled")
    private fun HubWebView(
        session: RunnerLlm.Session,
        onClose: () -> Unit,
    ) {
        val context = LocalContext.current
        val url = session.terminalUrl ?: session.url.orEmpty()
        var loading by remember(session.id) { mutableStateOf(true) }
        var error by remember(session.id) { mutableStateOf<String?>(null) }
        val webView = remember(session.id, url) {
            runCatching {
                WebView(context).apply {
                    // На чёрном фоне «протухающий» туннель выглядел как мёртвый экран.
                    setBackgroundColor(android.graphics.Color.WHITE)
                    isFocusable = true
                    isFocusableInTouchMode = true
                    settings.javaScriptEnabled = true
                    settings.domStorageEnabled = true
                    settings.loadWithOverviewMode = false
                    settings.useWideViewPort = false
                    settings.builtInZoomControls = false
                    settings.displayZoomControls = false
                    settings.mixedContentMode = android.webkit.WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
                    webViewClient = object : WebViewClient() {
                        override fun onReceivedHttpAuthRequest(
                            view: WebView?,
                            handler: HttpAuthHandler,
                            host: String?,
                            realm: String?,
                        ) {
                            runCatching { handler.proceed("yomikai", session.apiKey.orEmpty()) }
                        }

                        override fun onPageFinished(view: WebView?, url: String?) {
                            loading = false
                            error = null
                            view?.requestFocus()
                        }

                        override fun onReceivedError(
                            view: WebView?,
                            errorCode: Int,
                            description: String?,
                            failingUrl: String?,
                        ) {
                            loading = false
                            error = "Ошибка загрузки ($errorCode): $description"
                        }

                        override fun onReceivedHttpError(
                            view: WebView?,
                            request: android.webkit.WebResourceRequest?,
                            errorResponse: android.webkit.WebResourceResponse?,
                        ) {
                            loading = false
                            val code = errorResponse?.statusCode ?: 0
                            val mime = errorResponse?.mimeType.orEmpty()
                            // Discord api error format leaked through a proxy/token:
                            // {"success":false,"result":null,"errors":[{"code":10005,...}]}
                            val body = runCatching {
                                errorResponse?.data?.bufferedReader()?.use { it.readText() }.orEmpty()
                            }.getOrDefault("").take(300)
                            if (code == 405 || body.contains("method not allowed", ignoreCase = true)) {
                                error = "Ранер ответил $code (Method Not Allowed). Скорее всего в поле " +
                                    "GitHub PAT вставлен НЕ-GitHub токен (например Discord). Возьмите " +
                                    "настоящий GitHub PAT (ghp_/github_pat_). Ответ: $body"
                            } else {
                                error = "HTTP $code на сайте ранера" +
                                    body.takeIf { it.isNotBlank() }?.let { "\n$it" }.orEmpty()
                            }
                        }
                    }
                    if (url.isNotBlank()) loadUrl(url)
                }
            }.getOrElse {
                error = "WebView не создался: ${it.message ?: it}"
                null
            }
        }
        DisposableEffect(webView) {
            onDispose {
                runCatching {
                    (webView?.parent as? android.view.ViewGroup)?.removeView(webView)
                    webView?.stopLoading()
                    webView?.destroy()
                }
            }
        }

        Column(modifier = Modifier.fillMaxSize().statusBarsPadding()) {
            Row(
                modifier = Modifier.fillMaxWidth().padding(horizontal = 12.dp, vertical = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                Text(
                    "npm-hub • ${session.os}" +
                        (if (loading) " • подключение…" else " • сайт"),
                    style = MaterialTheme.typography.bodySmall,
                    modifier = Modifier.weight(1f),
                )
                IconButton(onClick = {
                    loading = true
                    error = null
                    runCatching { webView?.reload() }
                }) {
                    Icon(Icons.Outlined.Refresh, contentDescription = "Перезагрузить")
                }
                TextButton(onClick = onClose) { Text("Закрыть") }
            }
            if (webView != null && error == null) {
                AndroidView(
                    factory = { webView },
                    modifier = Modifier.fillMaxSize(),
                )
            } else {
                Column(
                    modifier = Modifier.fillMaxSize().padding(24.dp),
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(
                        error ?: "Сайт хаба недоступен. Проверьте, что ранер ещё жив.",
                        style = MaterialTheme.typography.bodyMedium,
                    )
                    FilledTonalButton(
                        onClick = { error = null; loading = true; runCatching { webView?.reload() } },
                    ) { Text("Попробовать снова") }
                    TextButton(onClick = onClose) { Text("Закрыть и к запуску") }
                }
            }
        }
    }
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.logcat
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get
import java.io.File

/**
 * Продвинутое управление историей AI-чата.
 *
 * Проблемы, которые решает:
 *  - История терялась при пересоздании вкладки / смене процесса (не было persist)
 *  - Тратил до 50к токенов на reasoning двух языков (нет лимита, нет сокращения)
 *  - Не говорил что доступно/невозможно (нет capability report)
 *
 * Решения:
 *  - Файл `workspace/ai_history.json` + StateFlow + лимит из `pref_ai_history_limit` (дефолт 12)
 *  - Токен-бюджет `pref_ai_token_budget` (дефолт 4000) — обрезка истории и max_tokens в запросе
 *  - Availability report перед каждым ходом: сеть, ключи, модели, ранер, локальная LLM
 *  - Сжатие истории: старые сообщения суммируются в краткий «контекст» вместо удаления
 */
object AiHistoryManager {

    @Serializable
    data class Msg(
        val role: String, // user | ai
        val text: String,
        val time: Long = System.currentTimeMillis(),
        val tokens: Int = 0,
        val model: String = "",
        val reasoning: String = "",
        val tools: List<String> = emptyList(),
        val files: List<String> = emptyList(),
        /** Кнопки-варианты [[...]] из ответа модели — повторная отправка текстом. */
        val choices: List<String> = emptyList(),
    )

    private const val FILE = "ai_history.json"
    private val json = Json { ignoreUnknownKeys = true; encodeDefaults = true }

    private fun prefs(): OcrPreferences = Injekt.get()

    /**
     * Канал истории. У книги их два: обычный чат и отыгрыш.
     *
     * Раньше файл был один на `mangaId`, поэтому переключение режима
     * подмешивало в реплику чужой разговор: в чате могли всплыть слова
     * отыгрыша, и наоборот. У отыгрыша своя история, общие знания книги
     * при этом остаются общими — изолируется переписка, а не память.
     */
    const val CHANNEL_CHAT = "chat"
    const val CHANNEL_ROLEPLAY = "roleplay"

    fun channelOf(mode: String): String =
        if (mode == BookChatProfile.MODE_ROLEPLAY) CHANNEL_ROLEPLAY else CHANNEL_CHAT

    /**
     * Файл истории. Старые файлы книг (`ai_history_<id>.json`) остаются
     * историей обычного чата — переименовывать их не нужно, иначе читатель
     * потерял бы переписку при обновлении.
     */
    fun historyFile(context: Context, mangaId: Long? = null, channel: String = CHANNEL_CHAT): File {
        val ws = aiWorkspaceDir(context)
        ws.mkdirs()
        return when {
            mangaId == null -> File(ws, FILE)
            channel == CHANNEL_CHAT -> File(ws, "ai_history_${mangaId}.json")
            else -> File(ws, "ai_history_${mangaId}_$channel.json")
        }
    }

    private fun aiWorkspaceDir(context: Context): File {
        // Yomikai workspace — /sdcard/Yomikai/AI или внутренние файлы как fallback
        val ext = context.getExternalFilesDir(null)
        val candidate = if (ext != null) File(ext, "../../Yomikai/AI").canonicalFile else File(context.filesDir, "ai_workspace")
        // Fallback если нет разрешения на ext
        return if (candidate.exists() || candidate.mkdirs()) candidate else File(context.filesDir, "ai_workspace")
    }

    fun load(context: Context, mangaId: Long? = null, channel: String = CHANNEL_CHAT): MutableList<Msg> {
        val f = historyFile(context, mangaId, channel)
        if (!f.exists()) return mutableListOf()
        return try {
            val raw = f.readText()
            val list = json.decodeFromString<List<Msg>>(raw)
            // Обрезаем до лимита при загрузке
            val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
            list.takeLast(limit).toMutableList()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "AiHistoryManager load failed" }
            mutableListOf()
        }
    }

    fun save(context: Context, history: List<Msg>, mangaId: Long? = null, channel: String = CHANNEL_CHAT) {
        try {
            val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
            val toSave = history.takeLast(limit)
            historyFile(context, mangaId, channel).writeText(json.encodeToString(toSave))
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "AiHistoryManager save failed" }
        }
    }

    fun append(
        context: Context,
        history: MutableList<Msg>,
        msg: Msg,
        mangaId: Long? = null,
        channel: String = CHANNEL_CHAT,
    ) {
        history.add(msg)
        val limit = prefs().aiHistoryLimit().get().coerceIn(4, 100)
        while (history.size > limit) {
            // Сжимаем: первые 2 сообщения → один summary
            val oldest = history.removeAt(0)
            val second = if (history.isNotEmpty()) history.removeAt(0) else null
            val summary = buildString {
                append("[Сжато: ")
                append(oldest.role).append(": ").append(oldest.text.take(80))
                if (second != null) append(" | ").append(second.role).append(": ").append(second.text.take(80))
                append("]")
            }
            history.add(0, Msg(role = "ai", text = summary, time = System.currentTimeMillis()))
        }
        save(context, history, mangaId, channel)
    }

    /**
     * Оценка токенов грубо: 1 токен ≈ 4 символа (для ru/en). Точнее — после ответа модели.
     */
    fun estimateTokens(text: String): Int = (text.length / 3.5).toInt().coerceAtLeast(1)

    fun totalTokens(history: List<Msg>): Int = history.sumOf { if (it.tokens > 0) it.tokens else estimateTokens(it.text) }

    fun trimToBudget(history: List<Msg>, budget: Int): List<Msg> {
        if (budget <= 0) return history
        var total = totalTokens(history)
        if (total <= budget) return history
        // Убираем старые, оставляя последние дорогие
        val mutable = history.toMutableList()
        while (mutable.size > 4 && total > budget * 0.85) {
            val removed = mutable.removeAt(0)
            total -= if (removed.tokens > 0) removed.tokens else estimateTokens(removed.text)
        }
        return mutable
    }
}

metadata.preview:
// Отправка, которая не теряет сообщение, поданное во время работы
// агента: оно встаёт в очередь и уходит следующим ходом.
val sendOrQueue: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
    when {
        text.isBlank() -> Unit
        // Идёт ход — копим. Больше одного сообщения в очередь не берём:
        // читателю важнее ответить сейчас, чем копить пачку.
        loading -> {
            if (queuedMessage == null) {
                queuedMessage = text to fileBytes
                input = ""
                attachedName = null
                attachedBytes = null
                showToast("Сообщение в очереди — уйдёт следом")
            }
        }
        else -> send(text, fileName, fileBytes)
    }
}

display.text:
    // Отправка, которая не теряет сообщение, поданное во время работы
    // агента: оно встаёт в очередь и уходит следующим ходом.
    val sendOrQueue: (String, String?, ByteArray?) -> Unit = { text, fileName, fileBytes ->
        when {
            text.isBlank() -> Unit
            // Идёт ход — копим. Больше одного сообщения в очередь не берём:
            // читателю важнее ответить сейчас, чем копить пачку.
            loading -> {
                if (queuedMessage == null) {
                    queuedMessage = text to fileBytes
                    input = ""
                    attachedName = null
                    attachedBytes = null
                    showToast("Сообщение в очереди — уйдёт следом")
                }
            }
            else -> send(text, fileName, fileBytes)
        }
    }

    // Стоп: прерываем ход агента и всё, что он успел запустить, — озвучку и
    // авточтение. Иначе остановленный ответ оставляет читателя вслух
    // читающую главу.
    val stopEverything: () -> Unit = {
        runningJob?.cancel()
        runningJob = null
        loading = false
        onStopRequested()
        showToast("Остановлено")
    }

    // Очередь уходит сама, как только освободился агент.
    LaunchedEffect(loading, queuedMessage) {
        val next = queuedMessage
        if (!loading && next != null) {
            queuedMessage = null
            send(next.first, null, next.second)
        }
    }

    // История книги грузится один раз на книгу: перечитывать её на каждый
    // ответ нельзя — файл на диске ещё не дописан, и перезагрузка стирала бы
    // сообщение, которое агент только что сохранил.
    // Канал входит в ключ: у отыгрыша своя переписка, и переключение режима
    // должно показывать именно её, а не смешанную с обычным чатом.
    LaunchedEffect(mangaId, historyChannel) {
        history.clear()
        history.addAll(AiHistoryManager.load(context, mangaId, historyChannel))
        runCatching { listState.scrollToItem((history.size - 1).coerceAtLeast(0)) }
    }

    // Сводка сессии — отдельный эффект: она меняется после ответа агента,
    // когда выучены новые правила/источники.
    LaunchedEffect(mangaId, sessionRefresh) {
        // Сессия книги создаётся при первом входе в чат, чтобы знания и
        // история этой книги не смешивались с глобальным AI-чатом.
        if (mangaId != null) {
            sessionLine = withContext(Dispatchers.IO) {
                eu.kanade.tachiyomi.data.ai.BookKnowledge.ensureSession(context, mangaId)
                eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, mangaId)
            }
        } else {
            sessionLine = eu.kanade.tachiyomi.data.ai.BookKnowledge.summaryLine(context, null)
        }
    }

    val fileLauncher = rememberLauncherForActivityResult(
        ActivityResultContracts.OpenDocument(),
    ) { uri: Uri? ->
        if (uri == null) return@rememberLauncherForActivityResult
        val (name, bytes) = readUriFile(context, uri) ?: return@rememberLauncherForActivityResult
        attachedName = name
        attachedBytes = bytes
    }

    Dialog(
        properties = DialogProperties(
            usePlatformDefaultWidth = false,
            decorFitsSystemWindows = false,
        ),
        onDismissRequest = onClose,
    ) {
        Surface(modifier = Modifier.fillMaxSize()) {
            Column(modifier = Modifier.fillMaxSize().background(MaterialTheme.colorScheme.background)) {
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp, vertical = 10.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Icon(
                        Icons.Outlined.SmartToy,
                        contentDescription = null,
                        tint = MaterialTheme.colorScheme.primary,
                        modifier = Modifier.size(22.dp),
                    )
                    Spacer(Modifier.width(8.dp))
                    Column(Modifier.weight(1f)) {
                        Text(
                            "AI-чат · $mangaTitle",
                            style = MaterialTheme.typography.titleMedium,
                            maxLines = 1,
                        )
                        Text(
                            chapterTitle ?: "читалка",
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            maxLines = 1,
                        )
                        if (backendLine.isNotBlank()) {
                            Text(
                                backendLine,
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                maxLines = 2,
                            )
                        }
                        if (sessionLine.isNotBlank()) {
                            Text(
                                "Сессия книги: $sessionLine",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                maxLines = 1,
                            )
                        }
                    }
                    IconButton(onClick = onClose) {
                        Icon(Icons.Outlined.Close, contentDescription = "Скрыть AI-чат")
                    }
                }
                // Переписка или файлы. Файлы — отдельная вкладка, а не
                // сообщение в чате: агент создаёт их и раньше, и читателю надо
                // увидеть весь список, а не то, что попало в последний ответ.
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp),
                    horizontalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    FilterChip(
                        selected = tab == 0,
                        onClick = { tab = 0 },
                        label = { Text("Чат") },
                        modifier = Modifier.height(30.dp),
                    )
                    FilterChip(
                        selected = tab == 1,
                        onClick = {
                            tab = 1
                            filesRefresh++
                        },
                        label = { Text("Файлы") },
                        modifier = Modifier.height(30.dp),
                    )
                }
                if (tab == 1) {
                    WorkspaceFilesPanel(
                        context = context,
                        refresh = filesRefresh,
                        onOpen = { file ->
                            runCatching {
                                context.startActivity(
                                    file.getUriCompat(context).toShareIntent(
                                        context = context,
                                        type = "application/octet-stream",
                                        message = file.name,
                                    ),
                                )
                            }.onFailure { showToast("Не удалось открыть файл") }
                        },
                    )
                } else {
                // Настройки работы с этой книгой: режим, 18+, цензура. Отдельный
                // рядом, а не в меню: переключать их надо прямо по ходу чтения.
                if (mangaId != null) {
                    val bookId = mangaId
                    // Профиль книги, а не Book: в UI нужны только настройки.
                    val applyProfile: ((BookKnowledge.Book) -> Unit) -> Unit = { mutate ->
                        bookSettings = BookKnowledge.updateProfile(context, bookId, mutate)
                            .let { BookChatProfile.Settings(it.mode, it.matureAllowed, it.censorship, it.title, it.edition) }
                    }
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp),
                        horizontalArrangement = Arrangement.spacedBy(6.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        FilterChip(
                            selected = bookSettings.mode == BookChatProfile.MODE_ROLEPLAY,
                            onClick = {
                                val next = if (bookSettings.mode == BookChatProfile.MODE_ROLEPLAY) {
                                    BookChatProfile.MODE_CHAT
                                } else {
                                    BookChatProfile.MODE_ROLEPLAY
                                }
                                applyProfile { it.mode = next }
                            },
                            label = { Text(BookChatProfile.modeTitle(bookSettings.mode)) },
                            modifier = Modifier.height(30.dp),
                        )
                        FilterChip(
                            selected = bookSettings.matureAllowed,
                            onClick = { applyProfile { it.matureAllowed = !it.matureAllowed } },
                            label = { Text("18+") },
                            modifier = Modifier.height(30.dp),
                        )
                        FilterChip(
                            selected = bookSettings.censorship,
                            onClick = { applyProfile { it.censorship = !it.censorship } },
                            label = { Text("Цензура") },
                            modifier = Modifier.height(30.dp),
                        )
                    }
                }
                if (loading || activity.isNotBlank()) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp, vertical = 2.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        if (loading) {
                            CircularProgressIndicator(Modifier.size(12.dp), strokeWidth = 2.dp)
                            Spacer(Modifier.width(6.dp))
                        }
                        Text(
                            buildString {
                                append(if (loading) "AI думает" else "Готово")
                                if (loading && elapsed > 0) append(" · ").append(elapsed).append(" с")
                                if (activity.isNotBlank()) append(" · ").append(activity)
                            },
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                            maxLines = 2,
                        )
                    }
                }
                HorizontalDivider()

                LazyColumn(
                    state = listState,
                    modifier = Modifier
                        .weight(1f)
                        .fillMaxWidth(),
                    contentPadding = androidx.compose.foundation.layout.PaddingValues(12.dp),
                    verticalArrangement = Arrangement.spacedBy(8.dp),
                ) {
                    if (history.isEmpty() && !loading) {
                        item {
                            Text(
                                "Спросите что угодно о книге «$mangaTitle»: " +
                                    "сюжет, персонажи, порядок чтения, перевод реплик, " +
                                    "«нарисуй лого», «сделай заметку»… AI умеет создавать " +
                                    "файлы в workspace, а результат можно скачать.",
                                style = MaterialTheme.typography.bodyMedium,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                textAlign = TextAlign.Center,
                                modifier = Modifier
                                    .fillMaxWidth()
                                    .padding(vertical = 16.dp),
                            )
                        }
                    }

                    itemsIndexed(history) { index, msg ->
                        ChatBubble(
                            context = context,
                            msg = msg,
                            isMine = msg.role == "user",
                            canPlay = msg.role == "ai",
                            onCopy = {
                                val clipboard = context.getSystemService(Context.CLIPBOARD_SERVICE)
                                    as? ClipboardManager
                                clipboard?.setPrimaryClip(ClipData.newPlainText("AI-чат", msg.text))
                                showToast("Скопировано")
                            },
                            onChoice = { choice ->
                                if (!loading) send(choice, null, null)
                            },
                            onRetry = {
                                if (!loading) {
                                    history.remove(msg)
                                    send(msg.text, null, null)
                                }
                            },
                            onDelete = {
                                history.remove(msg)
                                AiHistoryManager.save(context, history, mangaId, historyChannel)
                            },
                            onSpeak = {
                                TtsSpeaker.speak(context, msg.text)
                            },
                        )
                    }
                }

                AnimatedVisibility(visible = attachedName != null) {
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .padding(horizontal = 12.dp, vertical = 4.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(Icons.Outlined.AttachFile, contentDescription = null, modifier = Modifier.size(18.dp))
                        Spacer(Modifier.width(6.dp))
                        Text(
                            attachedName ?: "",
                            style = MaterialTheme.typography.bodySmall,
                            maxLines = 1,
                            modifier = Modifier.weight(1f),
                        )
                        TextButton(onClick = {
                            attachedName = null
                            attachedBytes = null
                        }) {
                            Text("Убрать")
                        }
                    }
                }

                QuickActionsRow(
                    enabled = !loading,
                    onImage = { input = "Нарисуй картинку: " },
                    onAudio = { input = "Создай аудиофайл (render_audio): " },
                    onVideo = { input = "Сделай видео: " },
                    onZip = { send("Упакуй workspace в zip и покажи готовый файл", null, null) },
                    onSource = { input = "Прочитай источник и выучи правила книги: " },
                    onRules = { input = "Выучи правила книги по этому тексту:\n" },
                )

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .navigationBarsPadding()
                        .imePadding()
                        .padding(horizontal = 12.dp, vertical = 8.dp),
                    verticalAlignment = Alignment.Bottom,
                ) {
                    OutlinedIconButton(
                        onClick = { fileLauncher.launch(arrayOf("*/*")) },
                        enabled = !loading,
                    ) {
                        Icon(Icons.Outlined.AttachFile, contentDescription = "Прикрепить файл")
                    }
                    Spacer(Modifier.width(8.dp))
                    OutlinedTextField(
                        value = input,
                        onValueChange = { input = it },
                        modifier = Modifier.weight(1f),
                        placeholder = {
                            Text(
                                if (queuedMessage != null) {
                                    "В очереди — уйдёт следом"
                                } else {
                                    "Сообщение AI…"
                                },
                            )
                        },
                        maxLines = 4,
                        // Ввод не блокируется на время работы агента: писать
                        // ему последовательно должно быть можно, иначе вопрос
                        // приходилось заранее писать в поле и ждать.
                        enabled = true,
                        keyboardOptions = KeyboardOptions(imeAction = ImeAction.Send),
                        keyboardActions = KeyboardActions(
                            onSend = {
                                sendOrQueue(input.trim(), attachedName, attachedBytes)
                            },
                        ),
                    )
                    Spacer(Modifier.width(8.dp))
                    OutlinedIconButton(
                        onClick = { sendOrQueue(input.trim(), attachedName, attachedBytes) },
                        enabled = input.isNotBlank(),
                    ) {
                        Icon(Icons.AutoMirrored.Outlined.Send, contentDescription = "Отправить")
                    }
                    // Стоп виден всегда, пока идёт ход: иначе ответ агента,
                    // а вместе с ним озвучка и авточтение, нечем остановить.
                    if (loading) {
                        Spacer(Modifier.width(4.dp))
                        FilledIconButton(onClick = stopEverything) {
                            Icon(Icons.Outlined.StopCircle, contentDescription = "Остановить")
                        }
                    }
                }

                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(horizontal = 12.dp, vertical = 6.dp),
                    horizontalArrangement = Arrangement.End,
                ) {
                    TextButton(onClick = { showClearConfirm = true }) {
                        Text("Очистить историю")
                    }
                }
            }
                }
        }
    }


    if (showClearConfirm) {
        androidx.compose.material3.AlertDialog(
            onDismissRequest = { showClearConfirm = false },
            title = { Text("Очистить историю чата?") },
            text = { Text("История этой книги будет удалена навсегда. Это действие нельзя отменить.") },
            confirmButton = {
                Button(onClick = {
                    history.clear()
                    AiHistoryManager.save(context, history, mangaId, historyChannel)
                    showClearConfirm = false
                    showToast("История очищена")
                }) {
                    Text("Очистить")
                }
            },
            dismissButton = {
                TextButton(onClick = { showClearConfirm = false }) { Text("Отмена") }
            },
        )
    }
}

private fun sendMessage(
    context: Context,
    scope: kotlinx.coroutines.CoroutineScope,
    mangaId: Long?,
    mangaTitle: String,
    chapterTitle: String?,
    input: String,
    attachmentsName: String? = null,
    attachmentsBytes: ByteArray? = null,
    history: SnapshotStateList<Msg>,
    loading: (Boolean) -> Unit,
    onScroll: (Int) -> Unit,
    /** Настройки книги на момент отправки: цензура применяется к ответу. */
    censorship: Boolean = true,
    /** Канал истории на момент отправки, чтобы ответ не попал в чужую переписку. */
    historyChannel: String = AiHistoryManager.CHANNEL_CHAT,
    onActivity: (String) -> Unit = {},
    /** Вызывается после сохранения ответа: пора перечитать сводку сессии. */
    onDone: () -> Unit = {},
) {
    AiHistoryManager.append(context, history, Msg(role = "user", text = input), mangaId, historyChannel)
    loading(true)
    onActivity("Запрос к модели…")
    scope.launch {

        val reply = runCatching {
            chatOnce(
                context = context,
                mangaId = mangaId,
                mangaTitle = mangaTitle,
                chapterTitle = chapterTitle,
                input = input,
                attachmentsName = attachmentsName,
                attachmentsBytes = attachmentsBytes,
                history = history,
                onProgress = onActivity,
            )
        }.getOrElse { error ->
            onActivity("Ошибка запроса")
            AiAgent.AgentReply(
                text = "Сбой запроса к AI: ${error.message ?: error::class.java.simpleName}",
                toolResults = emptyList(),
                images = emptyList(),
            )
        }
        // Фильтр грубых слов — настройка читателя, применяется к тому, что
        // реально попадёт в чат и в историю, иначе «цензура» была бы только
        // словами в промпте.
        val shown = if (censorship) {
            BookChatProfile.maskCensored(reply.text)
        } else {
            reply.text
        }
        // Пакетная генерация отдаёт несколько файлов одним вызовом: показываем
        // их все отдельными карточками, иначе читатель увидит одну картинку из
        // десяти и решит, что остальные не сделаны.
        val produced = reply.toolResults.flatMap { listOfNotNull(it.fileProduced) + it.extraFiles }
        val files = (produced + reply.images)
            .distinctBy { it.absolutePath }
            .mapNotNull { eu.kanade.tachiyomi.data.ai.AiWorkspace.relPathOrNull(context, it) }
            .distinct()
        AiHistoryManager.append(
            context = context,
            history = history,
            msg = Msg(
                role = "ai",
                text = shown,
                time = System.currentTimeMillis(),
                tokens = reply.tokens,
                model = reply.model,
                reasoning = reply.reasoning.orEmpty(),
                choices = reply.choices,
                tools = reply.toolResults.map { tr ->
                    buildString {
                        append(tr.name)
                        if (tr.status == "error") append(" — ошибка")
                        if (tr.tookMs > 0) append(" · ").append(tr.tookMs / 1000).append(" с")
                        val produced = tr.fileProduced
                        if (produced != null) {
                            append(" · ").append(produced.name).append(' ')
                            append(produced.length() / 1024).append(" КБ")
                        }
                        if (tr.extraFiles.isNotEmpty()) {
                            append(" · ещё ").append(tr.extraFiles.size)
                        }
                    }
                },
                files = files,
            ),
            mangaId = mangaId,
            channel = historyChannel,
        )
        loading(false)
        onActivity("Готово")
        onScroll(history.size - 1)
        onDone()
    }
}

// `}` внутри класса символов экранирован: без экрана ICU-движок регулярок
// (Android 13+, Itel/Infinix) бросает PatternSyntaxException в <clinit>.
private val linkRe = Regex("https?://[^\\s)\\]\\}\"']+", RegexOption.IGNORE_CASE)

/** Модель чата по текущему провайдеру — для заголовка и выбора ролей. */
private fun chatModelLabel(
    context: Context,
    prefs: mihon.domain.ocr.service.OcrPreferences,
): String {
    val provider = prefs.aiProvider().get()
    return when (provider) {
        eu.kanade.tachiyomi.data.ai.AiAssistant.PROVIDER_ZEN ->
            prefs.zenModel().get().ifBlank { eu.kanade.tachiyomi.data.ai.AiAssistant.ZEN_MODELS.first() }
        eu.kanade.tachiyomi.data.ai.AiAssistant.PROVIDER_OPENROUTER -> prefs.openrouterFreeModel().get()
            .ifBlank { eu.kanade.tachiyomi.data.ai.AiAssistant.OPENROUTER_FREE_FALLBACK.first() }
        else -> eu.kanade.tachiyomi.data.ai.AiProviders.userProvider(context, provider)?.model ?: provider
    }
}

private suspend fun chatOnce(
    context: Context,
    mangaId: Long?,
    mangaTitle: String,
    chapterTitle: String?,
    input: String,
    attachmentsName: String?,
    attachmentsBytes: ByteArray?,
    history: List<Msg>,
    onProgress: ((String) -> Unit)? = null,
): AiAgent.AgentReply =
    withContext(Dispatchers.IO) {
        val prefs = uy.kohesive.injekt.Injekt.get<mihon.domain.ocr.service.OcrPreferences>()
        val orchestrator = eu.kanade.tachiyomi.data.ai.AiModelRoles.orchestratorTarget(
            chatBackend = prefs.aiBackend().get(),
            chatProvider = prefs.aiProvider().get(),
            chatModel = chatModelLabel(context, prefs),
            orchestratorBackend = prefs.aiOrchestratorBackend().get(),
            orchestratorModel = prefs.aiOrchestratorModel().get(),
        )
        val resolution = AiBackends.resolve(
            context = context,
            backendId = orchestrator.backendId,
            modelOverride = orchestrator.modelOverride,
        )
        val chat = resolution.chat
        if (chat == null) {
            return@withContext AiAgent.AgentReply(
                text = resolution.message ?: "AI-бэкенд недоступен",
                toolResults = emptyList(),
                images = emptyList(),
            )
        }
        val attachedText = if (attachmentsName != null && attachmentsBytes != null) {
            val saved = eu.kanade.tachiyomi.data.ai.AiWorkspace.importAttachment(context, attachmentsName, attachmentsBytes)
            if (saved != null) {
                "Прикреплён файл: ${eu.kanade.tachiyomi.data.ai.AiWorkspace.relPath(context, saved)}"
            } else {
                "Прикреплён файл: $attachmentsName (не удалось сохранить)"
            }
        } else {
            null
        }
        val priorTurns = history
            .dropLast(1)
            .map { it.role to it.text }
            .takeLast(6)
        val knowledge = eu.kanade.tachiyomi.data.ai.BookKnowledge.render(context, mangaId)
            .ifBlank {
                "ЗНАНИЕ О КНИГЕ: пока ничего не проверено — выясни через web_search, " +
                    "прочитай найденную страницу через book_learn {\"url\":…} и сохрани правила."
            }
        // Присланная пользователем ссылка — это источник, а не вопрос: говорим
        // модели прямо, чтобы она прочитала страницу и зафиксировала правила.
        val links = linkRe.findAll(input).map { it.value }.distinct().take(3).toList()
        val prompt = buildString {
            append("Книга: ").append(mangaTitle)
            if (!chapterTitle.isNullOrBlank()) append("\nГлава: ").append(chapterTitle)
            if (links.isNotEmpty()) {
                append("\nПользователь прислал источник: ").append(links.joinToString(", "))
                append("\nПрочитай источник через book_learn {\"url\":\"…\"}, выведи из него правила ")
                append("(порядок чтения, области и рамки, баблы, расшифровка, голоса и роли) ")
                append("и зафиксируй их book_learn с kind. Если правил нет — так и скажи.")
            }
            // Читатель может сам продиктовать правило: такие слова помечаются
            // user=true, иначе в источниках книги не отличить его от догадок.
            if (mangaId != null) {
                append("\nЕсли в сообщении пользователя есть новые правила книги — сохрани их ")
                append("вызовами book_learn с kind и user=true, не пересказывая правило только текстом.")
            }
            append("\nВопрос: ").append(input)
        }
        AiAgent.run(
            context = context,
            userText = prompt,
            attachmentsInfo = attachedText,
            history = priorTurns,
            chatFn = chat,
            mangaId = mangaId,
            bookContext = knowledge,
            onProgress = onProgress,
        )
    }

private fun readUriFile(context: Context, uri: Uri): Pair<String, ByteArray>? =
    runCatching {
        val name = context.contentResolver.query(
            uri,
            null,
            null,
            null,
            null,
        )?.use { c ->
            val i = c.getColumnIndex(OpenableColumns.DISPLAY_NAME)
            if (i >= 0) c.getString(i) else null
        } ?: "file"
        val bytes = context.contentResolver.openInputStream(uri)?.use { it.readBytes() }
            ?: return@runCatching null
        name to bytes
    }.getOrNull()

@Composable
private fun ChatBubble(
    context: Context,
    msg: Msg,
    isMine: Boolean,
    canPlay: Boolean,
    onCopy: () -> Unit,
    onChoice: (String) -> Unit = {},
    onRetry: () -> Unit,
    onDelete: () -> Unit,
    onSpeak: () -> Unit,
) {
    val bubbleColor = if (isMine) {
        MaterialTheme.colorScheme.primaryContainer
    } else {
        MaterialTheme.colorScheme.surfaceVariant
    }
    val radius = RoundedCornerShape(
        topStart = 14.dp,
        topEnd = 14.dp,
        bottomStart = if (isMine) 14.dp else 4.dp,
        bottomEnd = if (isMine) 4.dp else 14.dp,
    )
    Column(
        modifier = Modifier
            .fillMaxWidth(),
        horizontalAlignment = if (isMine) Alignment.End else Alignment.Start,
    ) {
        Surface(
            color = bubbleColor,
            shape = radius,
            modifier = Modifier.fillMaxWidth(if (isMine) 0.85f else 0.95f),
        ) {
            Column(Modifier.padding(10.dp)) {
                if (msg.reasoning.isNotBlank()) {
                    var showReasoning by remember { mutableStateOf(false) }
                    Text(
                        if (showReasoning) "Размышления ▾" else "Размышления ▸",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.clickable { showReasoning = !showReasoning },
                    )
                    if (showReasoning) {
                        Text(
                            msg.reasoning.take(1200),
                            style = MaterialTheme.typography.bodySmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant,
                        )
                    }
                }
                SelectionContainer {
                    Text(
                        msg.text,
                        style = MaterialTheme.typography.bodyMedium,
                    )
                }
                if (!isMine && msg.choices.isNotEmpty()) {
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(top = 6.dp),
                        verticalArrangement = Arrangement.spacedBy(4.dp),
                    ) {
                        msg.choices.forEach { choice ->
                            OutlinedButton(
                                onClick = { onChoice(choice) },
                                modifier = Modifier.fillMaxWidth(),
                                contentPadding = PaddingValues(horizontal = 12.dp, vertical = 4.dp),
                            ) {
                                Text(
                                    choice,
                                    style = MaterialTheme.typography.labelMedium,
                                    maxLines = 2,
                                )
                            }
                        }
                    }
                }
                if (msg.tools.isNotEmpty()) {
                    var showTools by remember { mutableStateOf(false) }
                    Text(
                        if (showTools) "Инструменты (${msg.tools.size}) ▾" else "Инструменты (${msg.tools.size}) ▸",
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.clickable { showTools = !showTools }.padding(top = 4.dp),
                    )
                    if (showTools) {
                        msg.tools.forEach { line ->
                            Text(
                                "• $line",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                            )
                        }
                    }
                }
                msg.files.forEach { rel ->
                    val file = java.io.File(eu.kanade.tachiyomi.data.ai.AiWorkspace.root(context), rel)
                    Row(
                        modifier = Modifier.fillMaxWidth().padding(top = 4.dp),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        Icon(Icons.Outlined.AttachFile, contentDescription = null, modifier = Modifier.size(16.dp))
                        Spacer(Modifier.width(6.dp))
                        Column(Modifier.weight(1f)) {
                            Text(
                                file.name,
                                style = MaterialTheme.typography.labelMedium,
                                maxLines = 1,
                            )
                            Text(
                                rel + " · " + (file.length() / 1024) + " КБ",
                                style = MaterialTheme.typography.labelSmall,
                                color = MaterialTheme.colorScheme.onSurfaceVariant,
                                maxLines = 1,
                            )
                        }
                        TextButton(
                            onClick = {
                                if (!file.exists()) {
                                    context.toast("Файл не найден")
                                } else {
                                    runCatching {
                                        context.startActivity(
                                            file.getUriCompat(context).toShareIntent(
                                                context = context,
                                                type = "application/octet-stream",
                                                message = rel,
                                            ),
                                        )
                                    }.onFailure { context.toast("Не удалось открыть файл") }
                                }
                            },
                            enabled = file.exists(),
                        ) {
                            Text("Отправить")
                        }
                    }
                }
                Row(
                    modifier = Modifier.fillMaxWidth().padding(top = 4.dp),
                    horizontalArrangement = Arrangement.End,
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        buildString {
                            append(SimpleDateFormat("HH:mm", Locale.getDefault()).format(Date(msg.time)))
                            // Кто реально ответил: при автосмене моделей это не
                            // обязана быть выбранная в шапке, и без подписи это
                            // выглядит как «выбрали не ту модель».
                            if (msg.model.isNotBlank()) {
                                append(" · ").append(msg.model)
                            }
                            if (msg.tokens > 0) {
                                append(" · ").append(msg.tokens).append(" ток")
                            }
                        },
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        maxLines = 2,
                        modifier = Modifier.weight(1f),
                    )
                    IconButton(onClick = onCopy, modifier = Modifier.size(26.dp)) {
                        Icon(Icons.Outlined.ContentCopy, contentDescription = "Копировать", modifier = Modifier.size(14.dp))
                    }
                    IconButton(onClick = onRetry, modifier = Modifier.size(26.dp)) {
                        Icon(Icons.Outlined.Refresh, contentDescription = "Повторить", modifier = Modifier.size(14.dp))
                    }
                    if (canPlay) {
                        IconButton(onClick = onSpeak, modifier = Modifier.size(26.dp)) {
                            Icon(Icons.Outlined.GraphicEq, contentDescription = "Озвучить", modifier = Modifier.size(14.dp))
                        }
                    }
                    IconButton(onClick = onDelete, modifier = Modifier.size(26.dp)) {
                        Icon(Icons.Outlined.Delete, contentDescription = "Удалить", modifier = Modifier.size(14.dp))
                    }
                }
            }
        }
    }
}

