package eu.kanade.presentation.more.settings.screen

import android.content.Context
import androidx.compose.runtime.Composable
import androidx.compose.runtime.ReadOnlyComposable
import androidx.compose.runtime.remember
import androidx.compose.ui.platform.LocalContext
import eu.kanade.presentation.more.settings.Preference
import mihon.data.ocr.OcrPluginAvailability
import mihon.data.ocr.OcrPluginDescriptor
import mihon.data.ocr.OcrPluginRequirement
import mihon.data.ocr.OcrPlugins
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.isNetworkAvailable
import tachiyomi.i18n.MR
import tachiyomi.presentation.core.i18n.stringResource
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Реестр OCR-плагинов: что умеет приложение, что из этого доступно на этом
 * устройстве и почему недоступно остальное.
 *
 * Экран ничего не переключает — выбор движка делается в разделе «Распознавание
 * текста». Здесь видна полная картина: требования (сеть, пакет моделей, LiteRT,
 * API-ключ, адрес сервера), порядок во fallback-цепочке и поддержка областей.
 */
object SettingsOcrPluginsScreen : SearchableSettings {

    @ReadOnlyComposable
    @Composable
    override fun getTitleRes() = MR.strings.pref_ocr_plugins

    @Composable
    override fun getPreferences(): List<Preference> {
        val context = LocalContext.current
        val prefs = remember { Injekt.get<OcrPreferences>() }

        val online = rememberNetworkState(context)
        val availableIds = remember(online, prefs, context) {
            OcrPluginAvailability.availableIds(
                context = context,
                networkAvailable = online,
                hasApiKey = { plugin ->
                    when (plugin.id) {
                        "openrouter" -> prefs.openrouterApiKey().get().isNotBlank()
                        "google_ai" -> prefs.googleApiKey().get().isNotBlank()
                        else -> false
                    }
                },
                hasServerAddress = { prefs.owocrAddress().get().isNotBlank() },
            )
        }

        val selected = prefs.ocrModel().get()
        val chain = OcrPlugins.fallbackChain(
            primary = OcrPlugins.byModel(selected),
            preset = prefs.fallbackPreset().get(),
            networkAvailable = online,
        )

        return listOf(
            Preference.PreferenceGroup(
                title = stringResource(MR.strings.pref_ocr_plugins_group),
                preferenceItems = OcrPlugins.ALL.map { plugin ->
                    Preference.PreferenceItem.TextPreference(
                        title = pluginTitle(plugin, isSelected = plugin.model == selected),
                        subtitle = pluginSubtitle(plugin, availableIds),
                    )
                },
            ),
            Preference.PreferenceGroup(
                title = stringResource(MR.strings.pref_ocr_fallback),
                preferenceItems = listOf(
                    Preference.PreferenceItem.InfoPreference(
                        title = if (chain.isEmpty()) {
                            stringResource(MR.strings.pref_ocr_fallback_empty)
                        } else {
                            chain.joinToString(" → ") { it.title }
                        },
                    ),
                ),
            ),
        )
    }

    @Composable
    private fun pluginTitle(plugin: OcrPluginDescriptor, isSelected: Boolean): String {
        val badge = when {
            isSelected -> stringResource(MR.strings.pref_ocr_plugin_selected)
            plugin.online -> stringResource(MR.strings.pref_ocr_plugin_online)
            else -> stringResource(MR.strings.pref_ocr_plugin_offline)
        }
        val regions = if (plugin.supportsRegions) {
            " • " + stringResource(MR.strings.pref_ocr_plugin_regions)
        } else {
            ""
        }
        return "${plugin.title} — $badge$regions"
    }

    @Composable
    private fun pluginSubtitle(
        plugin: OcrPluginDescriptor,
        availableIds: Set<String>,
    ): String {
        val missing = OcrPluginAvailability.missingRequirement(plugin, availableIds)
        val state = if (missing == null) {
            stringResource(MR.strings.pref_ocr_plugin_available)
        } else {
            stringResource(MR.strings.pref_ocr_plugin_unavailable) + ": " + requirementName(missing)
        }
        return "${plugin.summary}\n$state"
    }

    @Composable
    private fun requirementName(requirement: OcrPluginRequirement): String = when (requirement) {
        OcrPluginRequirement.NETWORK -> stringResource(MR.strings.pref_plugin_requires_network)
        OcrPluginRequirement.MODEL_PACK -> stringResource(MR.strings.pref_plugin_requires_models)
        OcrPluginRequirement.LITERT -> stringResource(MR.strings.pref_plugin_requires_litert)
        OcrPluginRequirement.API_KEY -> stringResource(MR.strings.pref_plugin_requires_key)
        OcrPluginRequirement.SERVER_ADDRESS -> stringResource(MR.strings.pref_plugin_requires_server)
    }
}

@Composable
internal fun rememberNetworkState(context: Context): Boolean =
    remember(context) { isNetworkAvailable(context) }

package mihon.data.ocr

import android.content.Context

/**
 * Публичная проверка доступности OCR-плагинов для UI.
 *
 * Экраны настроек живут в модуле `app`, а `OcrModelFiles` и
 * `CyrillicOcrEngine` — `internal` в модуле `data`. Чтобы UI не тянул внутренности
 * движка и не дублировал список файлов пакета моделей, проверка собирается
 * здесь и отдаётся уже готовым множеством id.
 */
object OcrPluginAvailability {

    /**
     * Id плагинов, которые можно использовать прямо сейчас.
     *
     * @param networkAvailable есть ли интернет;
     * @param hasApiKey есть ли ключ у плагина (OpenRouter / Google AI);
     * @param hasServerAddress задан ли адрес своего сервера (OwOCR).
     */
    fun availableIds(
        context: Context,
        networkAvailable: Boolean,
        hasApiKey: (OcrPluginDescriptor) -> Boolean = { false },
        hasServerAddress: (OcrPluginDescriptor) -> Boolean = { false },
    ): Set<String> {
        val litertAvailable = runCatching {
            com.google.ai.edge.litert.Environment.create().close()
        }.isSuccess
        val modelsInstalled = OcrModelFiles.allInstalled(
            context,
            listOf(
                CyrillicOcrEngine.DETECTOR_PATH,
                CyrillicOcrEngine.PRIMARY_PATH,
                CyrillicOcrEngine.PRIMARY_DICT_PATH,
            ),
        )
        return OcrPlugins.available(
            networkAvailable = networkAvailable,
            modelsInstalled = modelsInstalled,
            litertAvailable = litertAvailable,
            hasApiKey = hasApiKey,
            hasServerAddress = hasServerAddress,
        ).map { it.id }.toSet()
    }

    /** Причина недоступности одним текстом — для подзаголовка в настройках. */
    fun missingRequirement(
        plugin: OcrPluginDescriptor,
        availableIds: Set<String>,
    ): OcrPluginRequirement? {
        if (plugin.id in availableIds) return null
        return plugin.requirements.firstOrNull()
    }
}

package eu.kanade.tachiyomi.data.ai

/**
 * Разделение моделей по ролям: OCR, обычный чат и агент-оркестратор.
 *
 * Раньше все три молча делили один и тот же выбор (`pref_ai_backend` +
 * `pref_ai_provider` + модель провайдера), поэтому «какая модель отвечает» не
 *льзя было ни объяснить, ни поменять по отдельности. Теперь у ролей свои
 * настройки, а если роль ничего не задала — она честно следует за чатом, и
 * это видно в статусе.
 */
enum class AiRole(val title: String) {
    OCR("OCR"),
    CHAT("Чат"),
    ORCHESTRATOR("Оркестратор"),
}

data class AiRoleTarget(
    val role: AiRole,
    /** Бэкенд, который реально обслуживает роль. */
    val backendId: String,
    val backendTitle: String,
    val provider: String,
    /**
     * Модель, которую роль показывает как рабочую. Если бэкенд выбирает
     * модель сам (локальная LLM, ранер), сюда попадает модель чата, а
     * [modelOverride] остаётся null — см. [modelHonoured].
     */
    val model: String,
    /** Модель, заданная именно для этой роли; null = берётся из чата. */
    val modelOverride: String? = null,
    /** Отдельный ли выбор у роли (false = следует за чатом). */
    val own: Boolean = false,
    /**
     * Применяется ли [modelOverride]. Локальная LLM и ранер работают на той
     * модели, которую выбрали в их настройках, поэтому роль может выбрать
     * только бэкенд; иначе статус врал бы пользователю.
     */
    val modelHonoured: Boolean = true,
)

object AiModelRoles {

    private fun backendTitle(id: String): String = AiBackends.byId(id).title

    /**
     * Роль OCR — это движок из настроек распознавания. Он не AI-провайдер, но
     * показывать его пользователю нужно в том же списке, иначе «три модели»
     * остаётся двумя.
     */
    fun ocrTarget(engineId: String, engineTitle: String): AiRoleTarget = AiRoleTarget(
        role = AiRole.OCR,
        backendId = "",
        backendTitle = "",
        provider = "",
        model = engineTitle.ifBlank { engineId },
    )

    fun chatTarget(chatBackend: String?, chatProvider: String, chatModel: String): AiRoleTarget =
        AiRoleTarget(
            role = AiRole.CHAT,
            backendId = AiBackends.byId(chatBackend).id,
            backendTitle = backendTitle(chatBackend.orEmpty()),
            provider = chatProvider,
            model = chatModel,
            // У чата свой выбор по определению: «как у чата» в его строке было бы
            // тавтологией.
            own = true,
        )

    /**
     * Оркестратор — агент читалки: он вызывает инструменты и выводит правила
     * книги. Пустые настройки означают «как у чата»: так поведение не
     * меняется у тех, кто ничего не выбирал.
     */
    fun orchestratorTarget(
        chatBackend: String?,
        chatProvider: String,
        chatModel: String,
        orchestratorBackend: String?,
        orchestratorModel: String?,
        /**
         * Состояние устройства: нужно ролям, чей бэкенд сам выбирает модель
         * (локальная LLM, ранер). Тогда статус показывает реальную модель
         * этого бэкенда, а не догадку. null — если состояние не собирали.
         */
        backendState: AiBackendState? = null,
    ): AiRoleTarget {
        // Неизвестный идентификатор бэкенда тоже считаем «своим выбор
        // отсутствует»: иначе роль молча уехала бы на онлайн вместо чата.
        val backendId = orchestratorBackend
            ?.takeIf { it.isNotBlank() }
            ?.let { raw -> AiBackends.ALL.firstOrNull { it.id == raw }?.id }
            ?: AiBackends.byId(chatBackend).id
        val backend = AiBackends.byId(backendId)
        val requested = orchestratorModel?.takeIf { it.isNotBlank() }
        // Модель роли применяется у онлайн-провайдера: у Zen и OpenRouter она
        // идёт в тело запроса, у своего провайдера — в модель payload с
        // откатом на его собственную. Локальная LLM и ранер работают на той
        // модели, что выбрали в их настройках, поэтому роль может выбрать
        // только бэкенд; иначе статус врал бы пользователю.
        val honoured = backend.supportsModelChoice
        val own = backendId != AiBackends.byId(chatBackend).id || requested != null
        val backendModel = if (honoured || backendState == null) {
            null
        } else {
            AiBackends.statusOf(backend, backendState, chatProvider).detail
        }
        return AiRoleTarget(
            role = AiRole.ORCHESTRATOR,
            backendId = backendId,
            backendTitle = backendTitle(backendId),
            provider = chatProvider,
            model = when {
                honoured -> requested ?: chatModel
                else -> backendModel?.takeIf { it.isNotBlank() } ?: chatModel
            },
            modelOverride = if (honoured) requested else null,
            own = own,
            modelHonoured = honoured,
        )
    }

    /** Строки статуса для UI: одна на роль, с пометкой «как у чата». */
    fun statusLines(vararg targets: AiRoleTarget): List<String> = targets.map { target ->
        val model = target.model.ifBlank { "не выбрана" }
        val tail = when {
            !target.own -> " · как у чата"
            !target.modelHonoured -> " · модель выбирает сам бэкенд"
            else -> ""
        }
        if (target.role == AiRole.OCR) {
            "${target.role.title}: $model"
        } else {
            "${target.role.title}: ${target.backendTitle} · ${target.provider} · $model$tail"
        }
    }
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import eu.kanade.tachiyomi.data.ai.AiAssistant.ChatReply
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.isNetworkAvailable
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Что нужно бэкенду AI-чата для работы. Те же категории, что у OCR- и
 * голосовых плагинов (`OcrPluginAvailability`, `VoiceRequirement`), чтобы
 * три реестра говорили с пользователем на одном языке.
 */
enum class AiRequirement {
    /** Нужен интернет (онлайн-провайдеры). */
    NETWORK,

    /** Нужен ключ OpenRouter. Без него Zen всё равно ответит, поэтому это не блокирующее требование. */
    OPENROUTER_KEY,

    /** Нужен GitHub PAT для запуска сессии на ранере. */
    GITHUB_PAT,

    /** Нужно разрешение «полу-онлайн LLM» в настройках вкладки AI. */
    RUNNER_ALLOWED,

    /** Нужна скачанная локальная модель из `LocalLlm.CATALOG`. */
    MODEL_DOWNLOAD,

    /** Нужна живая сессия ранера. */
    RUNNER_SESSION,
}

/** Снимок состояния устройства — всё, что нужно для честного статуса бэкенда. */
data class AiBackendState(
    val networkAvailable: Boolean,
    val hasOpenRouterKey: Boolean,
    val hasGithubPat: Boolean,
    val runnerAllowed: Boolean,
    val localModelId: String,
    val localModelInstalled: Boolean,
    val localModelSizeMb: Int,
    val runnerSessionAlive: Boolean,
)

/** Итог проверки: готов ли бэкенд и что именно ему мешает. */
data class AiBackendStatus(
    val available: Boolean,
    val missing: List<AiRequirement>,
    /** Что сейчас выбрано внутри бэкенда: провайдер, модель, сессия. */
    val detail: String,
)

/**
 * РЕЕСТР БЭКЕНДОВ AI-ЧАТА — «плагины» AI, по образцу `OcrPlugins` и
 * `VoicePlugins`.
 *
 * Ключи совпадают со значениями настройки `pref_ai_backend`, поэтому реестр
 * не вводит собственного состояния: что выбрано во вкладке AI, то и здесь.
 *
 * Второй задачей реестр убирает дублирование маршрутизации: раньше проверка
 * «готова ли локальная модель / есть ли живая сессия ранера» была зашита
 * прямо в `AiChatTab.send()`. Теперь это `resolve()`, и ровно ту же проверку
 * может показать экран настроек, не копируя логику.
 */
object AiBackends {

    /** Значения `pref_ai_backend`. */
    const val BACKEND_ONLINE = "online"
    const val BACKEND_LOCAL = "local"
    const val BACKEND_RUNNER = "runner"

    /**
     * Подпись функции чата, которую ждёт `AiAgent.run(chatFn = …)`.
     *
     * Это именно `typealias`, а не `fun interface`: `AiAgent.run` принимает
     * обычную suspend-функцию, и SAM-преобразование suspend-типов здесь ни к
     * чему — с алиасом типы совпадают буквально.
     */
    typealias ChatFn = suspend (prompt: String, system: String) -> ChatReply?

    /**
     * Результат маршрутизации: либо готовая функция чата, либо `message` —
     * готовый текст объяснения для пользователя (почему бэкенд не ответил).
     */
    data class Resolution(
        val backendId: String,
        val chat: ChatFn?,
        val message: String? = null,
    ) {
        val ready: Boolean get() = chat != null
    }

    data class Plugin(
        /** Значение настройки `pref_ai_backend`. */
        val id: String,
        val title: String,
        val summary: String,
        /** Работает без интернета. */
        val offline: Boolean,
        /** Требования, без которых бэкенд не ответит. */
        val requirements: List<AiRequirement>,
        /** Требования-подсказки: их отсутствие не блокирует работу. */
        val optionalRequirements: List<AiRequirement> = emptyList(),
        /**
         * Умеет ли бэкенд работать на конкретной модели — нужно ролям вроде
         * оркестратора. У онлайна выбор есть (OpenRouter принимает любой id
         * каталога, Zen — из `AiAssistant.ZEN_MODELS`), а локальная модель и
         * ранер модель выбирают сами: там роль может выбрать только бэкенд.
         */
        val supportsModelChoice: Boolean = true,
    )

    val ONLINE = Plugin(
        id = BACKEND_ONLINE,
        title = "Онлайн (Zen / OpenRouter)",
        summary = "Бесплатные модели Zen без ключа; при указанном ключе OpenRouter — его модель " +
            "и автосмена на Zen при лимите. Инструменты агента исполняет приложение.",
        offline = false,
        requirements = listOf(AiRequirement.NETWORK),
        optionalRequirements = listOf(AiRequirement.OPENROUTER_KEY),
    )

    val LOCAL = Plugin(
        id = BACKEND_LOCAL,
        title = "Локальная LLM",
        summary = "Модель на устройстве (LiteRT/.task из LocalLlm.CATALOG). Полностью офлайн, " +
            "инструменты агента доступны так же, как и онлайн.",
        offline = true,
        requirements = listOf(AiRequirement.MODEL_DOWNLOAD),
        supportsModelChoice = false,
    )

    val RUNNER = Plugin(
        id = BACKEND_RUNNER,
        title = "Полу-онлайн (GitHub Runner)",
        summary = "Модель запускается на GitHub-ранере через llm-runner.yml и отвечает по HTTP. " +
            "Нужны PAT и живая сессия.",
        offline = false,
        requirements = listOf(
            AiRequirement.NETWORK,
            AiRequirement.GITHUB_PAT,
            AiRequirement.RUNNER_ALLOWED,
            AiRequirement.RUNNER_SESSION,
        ),
        supportsModelChoice = false,
    )

    val ALL = listOf(ONLINE, LOCAL, RUNNER)

    fun byId(id: String?): Plugin = ALL.firstOrNull { it.id == id } ?: ONLINE

    /**
     * Статус бэкенда по снимку состояния. Чистая функция — её можно
     * проверять тестами без Android.
     *
     * @param provider значение `pref_ai_provider` (zen | openrouter) — нужно,
     *   чтобы показать фактический онлайн-провайдер в `detail`.
     */
    fun statusOf(
        plugin: Plugin,
        state: AiBackendState,
        provider: String = AiAssistant.PROVIDER_ZEN,
    ): AiBackendStatus {
        val missing = mutableListOf<AiRequirement>()
        val detail: String
        when (plugin.id) {
            BACKEND_ONLINE -> {
                if (!state.networkAvailable) missing += AiRequirement.NETWORK
                val openRouter = provider == AiAssistant.PROVIDER_OPENROUTER
                if (openRouter && !state.hasOpenRouterKey) missing += AiRequirement.OPENROUTER_KEY
                detail = if (openRouter && state.hasOpenRouterKey) {
                    "Провайдер: OpenRouter, автосмена на Zen при лимите"
                } else {
                    "Провайдер: Zen (без ключа)"
                }
            }

            BACKEND_LOCAL -> {
                if (!state.localModelInstalled) missing += AiRequirement.MODEL_DOWNLOAD
                detail = when {
                    state.localModelId.isBlank() -> "Модель не выбрана"
                    state.localModelSizeMb > 0 ->
                        "${state.localModelId} • ${state.localModelSizeMb} МБ" +
                            if (state.localModelInstalled) " • установлена" else " • не скачана"
                    else -> state.localModelId
                }
            }

            else -> {
                if (!state.networkAvailable) missing += AiRequirement.NETWORK
                if (!state.hasGithubPat) missing += AiRequirement.GITHUB_PAT
                if (!state.runnerAllowed) missing += AiRequirement.RUNNER_ALLOWED
                if (!state.runnerSessionAlive) missing += AiRequirement.RUNNER_SESSION
                detail = when {
                    !state.runnerAllowed -> "Разрешение ранера выключено"
                    state.runnerSessionAlive -> "Сессия ранера активна"
                    else -> "Нет живой сессии ранера"
                }
            }
        }
        return AiBackendStatus(
            available = missing.isEmpty(),
            missing = missing.toList(),
            detail = detail,
        )
    }

    /** Читает состояние устройства: настройки + файлы моделей + сессии ранера. */
    fun state(context: Context, prefs: OcrPreferences = Injekt.get()): AiBackendState {
        val modelId = prefs.localLlmModel().get()
        val model = LocalLlm.CATALOG.firstOrNull { it.id == modelId }
        val session = liveRunnerSession(context)
        return AiBackendState(
            // Сеть нужна только для статуса: сам resolve() её не требует,
            // потому что онлайн-провайдеры и так отвечают null при сбое.
            networkAvailable = isNetworkAvailable(context),
            hasOpenRouterKey = prefs.openrouterApiKey().get().isNotBlank(),
            hasGithubPat = prefs.githubPat().get().isNotBlank(),
            runnerAllowed = prefs.aiAllowRunner().get(),
            localModelId = modelId,
            localModelInstalled = model != null && runCatching {
                LocalLlm.isInstalled(context, model)
            }.getOrDefault(false),
            localModelSizeMb = model?.sizeMb ?: 0,
            runnerSessionAlive = session?.url != null,
        )
    }

    /**
     * Готов ли бэкенд отвечать и что сказать пользователю, если нет.
     *
     * Чистая функция (без `Context`), поэтому маршрутизация проверяется
     * юнит-тестами, а `resolve()` ниже лишь навешивает на неё реальную
     * функцию чата.
     */
    fun route(backendId: String?, state: AiBackendState): Route {
        val plugin = byId(backendId)
        return when (plugin.id) {
            BACKEND_LOCAL ->
                if (state.localModelId.isNotBlank() && state.localModelInstalled) {
                    Route(plugin.id, ready = true)
                } else {
                    Route(
                        plugin.id,
                        ready = false,
                        message = "Локальная модель не готова: скачайте её в ⚙ → Локальные LLM и прогоните «Тест»",
                    )
                }

            BACKEND_RUNNER ->
                if (state.runnerSessionAlive) {
                    Route(plugin.id, ready = true)
                } else {
                    Route(
                        plugin.id,
                        ready = false,
                        message = "Нет живой ранер-сессии: запустите её в ⚙ → Полу-онлайн LLM",
                    )
                }

            // Онлайн-бэкенд готов всегда: сеть и ключи проверяет сам
            // AiAssistant, а при сбое возвращает null — чат показывает это
            // пользователю вместо падения.
            else -> Route(plugin.id, ready = true)
        }
    }

    /** Вердикт `route()`: какой бэкенд выбран, готов ли он, что сказать. */
    data class Route(val backendId: String, val ready: Boolean, val message: String? = null)

    /**
     * Выбор бэкенда для запроса. Поведение совпадает с прежней маршрутизацией
     * вкладки AI: неизвестное или пустое значение читается как «онлайн»,
     * локальная модель и ранер проверяются на готовность, а при неготовности
     * возвращается текст объяснения вместо тихого падения.
     */
    fun resolve(
        context: Context,
        backendId: String?,
        state: AiBackendState = state(context),
        maxTokens: Int = DEFAULT_MAX_TOKENS,
        modelOverride: String? = null,
    ): Resolution {
        val plugin = byId(backendId)
        val route = route(plugin.id, state)
        if (!route.ready) {
            return Resolution(plugin.id, chat = null, message = route.message)
        }
        return when (plugin.id) {
            BACKEND_LOCAL -> {
                val model = LocalLlm.CATALOG.firstOrNull { it.id == state.localModelId }
                if (model != null && state.localModelInstalled) {
                    Resolution(
                        backendId = plugin.id,
                        chat = { prompt, system ->
                            LocalLlm.chat(context, model, "$system\n\n$prompt")
                                ?.let { ChatReply(it, null, model.name) }
                        },
                    )
                } else {
                    Resolution(plugin.id, chat = null, message = route.message)
                }
            }

            BACKEND_RUNNER -> {
val session = liveRunnerSession(context)
                if (session?.url != null) {
                    Resolution(
                        backendId = plugin.id,
                        chat = { prompt, system ->
                            RunnerLlm.chat(context, session, "$system\n\n$prompt")
                                ?.let { ChatReply(it, null, session.model) }
                        },
                    )
                } else {
                    Resolution(plugin.id, chat = null, message = route.message)
                }
            }

            else -> Resolution(
                backendId = plugin.id,
                chat = { prompt, system -> AiAssistant.chatFull(prompt, system, maxTokens, modelOverride) },
            )
        }
    }

    /** Столько токенов просил чат вкладки AI до появления реестра. */
    const val DEFAULT_MAX_TOKENS = 1800

    /**
     * Живая ранер-сессия: URL И непустой apiKey. Сессия без ключа (её могла
     * создать hub-ветка, где ключ не пишется в файл) для чата бесполезна —
     * `RunnerLlm.chat` возвращает null, поэтому учитывать её как «активную»
     * нельзя, иначе UI показывает «сессия активна», а ответов нет.
     */
    private fun liveRunnerSession(context: Context): RunnerLlm.Session? =
        runCatching {
            RunnerLlm.listSessions(context).firstOrNull { s ->
                !s.url.isNullOrBlank() && !s.apiKey.isNullOrBlank()
            }
        }.getOrNull()
}

package eu.kanade.tachiyomi.data.ai

import android.content.Context
import android.net.ConnectivityManager
import android.net.NetworkCapabilities
import mihon.domain.ocr.service.OcrPreferences
import java.io.File
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Отчёт о доступности: что возможно / что невозможно и почему.
 *
 * Пользователь жаловался: агент тратит 50к токенов на размышления и не говорит,
 * что доступно, а что нет. Теперь перед каждым ходом формируется краткий
 * capability-блок, который вставляется в системный промпт и показывается в UI.
 */
object AiCapabilityReporter {

    data class Capability(
        val name: String,
        val available: Boolean,
        val reason: String,
    )

    fun collect(context: Context): List<Capability> {
        val prefs: OcrPreferences = Injekt.get()
        val hasNetwork = isNetworkAvailable(context)
        val hasGoogleKey = prefs.googleApiKey().get().isNotBlank()
        val hasOpenRouterKey = prefs.openrouterApiKey().get().isNotBlank()
        val hasElevenKey = prefs.elevenApiKey().get().isNotBlank()
        val hasGithubPat = prefs.githubPat().get().isNotBlank()
        val allowRunner = prefs.aiAllowRunner().get()
        val allowGithub = prefs.aiAllowGithub().get()
        val backend = prefs.aiBackend().get()

        // Zen: доступность выводится из фактического ответа, а не из наличия
        // сети. Раньше здесь стояло `hasNetwork`, и отчёт писал «доступно» даже
        // при HTTP 403 FreeTierError — агент верил отчёту и по инструкции
        // «не повторяй недоступное» продолжал пробовать закрытый путь.
        val zenVerdict = ZenAvailability.describe(
            hasNetwork = hasNetwork,
            state = AiAssistant.zenState(),
        )

        return listOf(
            Capability("Интернет", hasNetwork, if (hasNetwork) "OK" else "Нет сети — онлайн OCR/TTS/AI не работают"),
            Capability("Google AI (Gemini) — пол говорящих, OCR онлайн", hasGoogleKey && hasNetwork, when {
                !hasNetwork -> "Нет сети"
                !hasGoogleKey -> "Нет ключа в Настройки → Распознавание → Google AI"
                else -> "OK"
            }),
            Capability("OpenRouter", hasOpenRouterKey && hasNetwork, if (hasNetwork && !hasOpenRouterKey) "Нет ключа" else if (!hasNetwork) "Нет сети" else "OK"),
            Capability("Zen free (без ключа)", zenVerdict.first, zenVerdict.second),
            Capability("ElevenLabs нейроголос", hasElevenKey && hasNetwork, if (!hasElevenKey) "Нет ключа ElevenLabs" else if (!hasNetwork) "Нет сети" else "OK"),
            Capability("TTS-сервер (ПК/ранер)", prefs.remoteTtsUrl().get().isNotBlank(), if (prefs.remoteTtsUrl().get().isBlank()) "Не указан адрес в Настройки → Голос" else "OK"),
            Capability("GitHub-ранер LLM", hasGithubPat && allowRunner && hasNetwork, when {
                !hasNetwork -> "Нет сети"
                !hasGithubPat -> "Нет PAT в Настройки → AI"
                !allowRunner -> "Выключено в Настройки → AI → Разрешить ранер"
                else -> "OK"
            }),
            Capability("GitHub API", hasGithubPat && allowGithub && hasNetwork, when {
                !hasNetwork -> "Нет сети"
                !hasGithubPat -> "Нет PAT"
                !allowGithub -> "Выключено в Настройки → AI"
                else -> "OK"
            }),
            Capability("Локальная LLM (.task в /sdcard/Yomikai/models)", FileProbe.hasLocalLlm(context), if (!FileProbe.hasLocalLlm(context)) "Нет .task модели" else "OK"),
            Capability("Бэкенд чата: $backend", true, when (backend) {
                "online" -> if (hasNetwork) "OK" else "Нет сети"
                "local" -> if (FileProbe.hasLocalLlm(context)) "OK" else "Нет модели"
                "runner" -> if (hasGithubPat && allowRunner) "OK" else "См. выше"
                else -> "Неизвестный бэкенд"
            }),
        )
    }

    fun renderForPrompt(context: Context): String {
        val caps = collect(context)
        return buildString {
            append("Доступность на этом устройстве (что возможно, что нет и почему):\n")
            caps.forEach { c ->
                append(if (c.available) "✅ " else "❌ ")
                append(c.name).append(": ").append(if (c.available) "доступно" else "недоступно")
                if (c.reason != "OK") append(" — ").append(c.reason)
                append("\n")
            }
            append("\nПравила: если функция недоступна — объясни причину и как включить; не трать токены на повторные попытки недоступного; отвечай на русском; reasoning кратко, не дублируй на двух языках.")
        }
    }

    fun renderForUi(context: Context): String {
        val caps = collect(context)
        val bad = caps.filter { !it.available }
        return if (bad.isEmpty()) "✅ Все основные функции доступны"
        else bad.joinToString("\n") { "❌ ${it.name}: ${it.reason}" }
    }

    private fun isNetworkAvailable(context: Context): Boolean {
        return try {
            val cm = context.getSystemService(Context.CONNECTIVITY_SERVICE) as ConnectivityManager
            val caps = cm.getNetworkCapabilities(cm.activeNetwork)
            caps?.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) == true
        } catch (_: Exception) { false }
    }

    private object FileProbe {
        fun hasLocalLlm(context: Context): Boolean {
            val candidates = listOf(
                File(context.getExternalFilesDir(null), "../../Yomikai/models").canonicalFile,
                File(context.filesDir, "models"),
            )
            return candidates.any { dir ->
                dir.exists() && dir.listFiles()?.any { it.name.endsWith(".task") } == true
            }
        }
    }
}

