package eu.kanade.tachiyomi.data.tts

/**
 * Лёгкий ручной JSON-разбор/сериализация словарей голосов и интонаций.
 *
 * org.json живёт только внутри Android, а в юнит-тестах app-модуля он не
 * замокан и бросает при любом обращении. Словари должны читаться и в тестах,
 * поэтому формат (массив объектов) разбирается этим хелпером независимо.
 */
internal object VoiceJson {

    /** Клоч JSON-массива: `[{"k":"v"},{"k":"v"}]` → список карт. */
    fun parseObjects(json: String): List<Map<String, String>> {
        val trimmed = json.trim()
        if (!trimmed.startsWith("[") || !trimmed.endsWith("]")) return parseObject(trimmed).let { if (it.isEmpty()) emptyList() else listOf(it) }
        val inner = trimmed.removePrefix("[").removeSuffix("]").trim()
        if (inner.isEmpty()) return emptyList()
        val result = mutableListOf<Map<String, String>>()
        var i = 0
        while (i < inner.length) {
            val objStart = inner.indexOf('{', i)
            if (objStart < 0) break
            var depth = 0
            var inStr = false
            var m = objStart
            var end = objStart
            while (m < inner.length) {
                val c = inner[m]
                if (inStr) {
                    if (c == '\\') { m += 2; continue }
                    if (c == '"') inStr = false
                } else {
                    when (c) {
                        '"' -> inStr = true
                        '{' -> depth++
                        '}' -> {
                            depth--
                            if (depth == 0) { end = m; break }
                        }
                    }
                }
                m++
            }
            val objText = inner.substring(objStart, end + 1)
            result.add(parseObject(objText))
            i = end + 1
        }
        return result
    }

    internal fun parseObject(text: String): Map<String, String> {
        val map = mutableMapOf<String, String>()
        val t = text.trim()
        if (!t.startsWith("{") || !t.endsWith("}")) return map
        val inner = t.removePrefix("{").removeSuffix("}").trim()
        if (inner.isEmpty()) return map
        for (pair in splitTopLevel(inner)) {
            val colon = pair.indexOf(':')
            if (colon <= 0) continue
            val key = unquote(pair.substring(0, colon).trim())
            val value = unquote(pair.substring(colon + 1).trim())
            map[key] = value
        }
        return map
    }

    /** Разбирает массив `["a","b"]` в список токенов. */
    fun parseArrayTokens(s: String): List<String> {
        val t = s.trim()
        if (!t.startsWith("[") || !t.endsWith("]")) {
            // Единичная метка без скобок.
            return if (t.isNotBlank()) listOf(unquote(t)) else emptyList()
        }
        val inner = t.removePrefix("[").removeSuffix("]").trim()
        if (inner.isEmpty()) return emptyList()
        return splitTopLevel(inner).map(::unquote).filter { it.isNotBlank() }
    }

    /** Разбивает содержимое по запятым нулевого уровня (не в строке и не в скобках). */
    internal fun splitTopLevel(text: String): List<String> {
        val result = mutableListOf<String>()
        var depth = 0
        var inStr = false
        var start = 0
        var i = 0
        while (i < text.length) {
            val c = text[i]
            if (inStr) {
                if (c == '\\') { i += 2; continue }
                if (c == '"') inStr = false
            } else {
                when (c) {
                    '"' -> inStr = true
                    '{', '[', '(' -> depth++
                    '}', ']', ')' -> depth--
                    ',' -> if (depth == 0) { result.add(text.substring(start, i)); start = i + 1 }
                }
            }
            i++
        }
        if (start < text.length) result.add(text.substring(start))
        return result
    }

    /** Снимает кавычки со строки, если они есть. */
    internal fun unquote(s: String): String {
        val t = s.trim()
        if (t.length >= 2 && t.first() == '"' && t.last() == '"') {
            return t.substring(1, t.length - 1).replace("\\\"", "\"")
        }
        return t
    }

    fun jsonEscape(s: String): String = buildString(s.length) {
        for (c in s) {
            when (c) {
                '"' -> append("\\\"")
                '\\' -> append("\\\\")
                '\n' -> append("\\n")
                '\r' -> append("\\r")
                '\t' -> append("\\t")
                else -> append(c.coerceAtLeast(' '))
            }
        }
    }
}

package eu.kanade.tachiyomi.data.tts

import android.speech.tts.TextToSpeech
import android.speech.tts.Voice
import logcat.LogPriority
import tachiyomi.core.common.util.system.logcat
import java.util.Locale

enum class VoiceKind { FEMALE, MALE, TEEN, OTHER }

/**
 * Классификация системных голосов по полу и подбор голоса для реплики.
 *
 * Важно: у Google Speech Services (самый распространённый движок на Android)
 * голоса называются НЕ по именам, а кодами вида `ru-ru-x-dfc-local`,
 * `ru-ru-x-ruf-network`. Прежняя версия искала в имени «svetlana»/«dmitry»
 * (это стиль Яндекс/RHVoice), поэтому все Google-голоса попадали в OTHER,
 * и pick(FEMALE)/pick(MALE) возвращали один и тот же первый голос — из-за
 * этого «работал только один голос».
 *
 * Теперь классификация трёхступенчатая:
 * 1. [Voice.getFeatures] / имя содержит явный признак пола;
 * 2. таблица известных кодов Google (`dfc`, `ruf`, … — женские; `rud`, `rue`,
 *    … — мужские) — коды берутся из середины имени `xx-xx-x-CODE-local`;
 * 3. детерминированный запасной вариант: голоса сортируются и делятся между
 *    полами по индексу, чтобы разные роли всё равно звучали по-разному.
 */
object VoiceHelper {
    private val femaleHints = listOf(
        "female", "woman", "svetlana", "milena", "oksana", "irina", "jane", "ksenia",
        "alena", "yelena", "elena", "anna", "arina", "maria", "natalia", "natalya",
        "tatiana", "tatyana", "victoria", "lyubov", "marianna", "жен", "женск", "девуш",
    )
    private val maleHints = listOf(
        "male", "man", "dmitry", "dmitri", "ermil", "filipp", "zahar", "pavel",
        "alexander", "aleksandr", "artemiy", "evgeniy", "mikhail", "vitaliy", "yuriy",
        "timofey", "seva", "anatol", "volodymyr", "maxim", "andrey", "ivan", "sergey", "муж",
    )
    private val teenHints = listOf("child", "kid", "teen", "young", "дет", "подрост", "umka")
    private val blacklist = listOf("locale", "default", "test")

    /**
     * Some OEM Android builds return an empty getVoices() set for RHVoice,
     * even though setVoice(name) and synthesis work. RHVoice validates a
     * manually constructed Voice by its name, so this catalog is used only as
     * a last-resort probe and only installed/enabled names are retained.
     */
    private val rhVoiceCatalog = mapOf(
        "ru" to listOf(
            "Aleksandr", "Aleksandr-hq", "Anna", "Arina", "Artemiy", "Elena",
            "Evgeniy-Rus", "Irina", "Mikhail", "Pavel", "Seva", "Tatiana",
            "Timofey", "Umka", "Victoria", "Vitaliy", "Yuriy",
        ),
        "en" to listOf("Alan", "BDL", "CLB", "Evgeniy-Eng", "Lyubov", "SLT"),
        "uk" to listOf("Anatol", "Marianna", "Natalia", "Volodymyr"),
    )

    private val languageAliases = mapOf(
        "ru" to setOf("ru", "rus"),
        "en" to setOf("en", "eng"),
        "ja" to setOf("ja", "jpn"),
        "ko" to setOf("ko", "kor"),
        "zh" to setOf("zh", "zho", "chi"),
        "uk" to setOf("uk", "ukr"),
    )

    /**
     * Коды голосов Google Speech Services. Имя выглядит как
     * `ru-ru-x-dfc-local`, значащая часть — предпоследний сегмент.
     */
    private val googleFemaleCodes = setOf(
        // ru
        "dfc", "ruf", "rug",
        // en
        "iob", "iog", "sfg", "tpc", "tpf", "jomn", "iol",
        // прочие распространённые
        "afb", "bfa", "cfa", "dfa", "dfb", "efa", "ffa", "gfa", "hfa", "sfb",
    )
    private val googleMaleCodes = setOf(
        // ru
        "rue", "rud", "dmc",
        // en
        "iom", "iog2", "tpd", "sfb2", "jomn2",
        // прочие распространённые
        "ama", "bma", "cma", "dma", "dmb", "ema", "fma", "gma", "hma", "smb",
    )

    fun russianVoices(tts: TextToSpeech?, enginePackage: String? = null): List<Voice> =
        voicesFor(tts, "ru", enginePackage)

    /** Ask a lazy TTS engine to load the requested language before getVoices(). */
    fun prepareForLanguage(tts: TextToSpeech?, language: String): Int {
        val engine = tts ?: return TextToSpeech.ERROR
        val locale = localeFor(language)
        runCatching { engine.isLanguageAvailable(locale) }
        return runCatching { engine.setLanguage(locale) }.getOrDefault(TextToSpeech.ERROR)
    }

    /**
     * Все голоса движка БЕЗ языкового фильтра.
     *
     * Нужно там, где жёсткий фильтр по языку оставляет пустой список: часть
     * OEM-движков не отдаёт ru-голоса, пока не докачан языковой пакет, и
     * `voicesFor(tts, "ru")` возвращает пусто при заведомо рабочем движке —
     * список в настройках выглядел пустым, а приложение требовало «установите
     * TTS-движок». [voicesFor] намеренно не меняется: он остаётся точным
     * выбором языка, а откат делает вызывающий UI.
     */
    fun allVoices(tts: TextToSpeech?, enginePackage: String? = null): List<Voice> {
        val engine = tts ?: return emptyList()
        val packageName = enginePackage?.takeIf { it.isNotBlank() }
            ?: runCatching { engine.defaultEngine }.getOrNull()
        val fromEngine = try {
            engine.voices.orEmpty()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "voices() failed" }
            emptySet()
        }.filterNot { voice ->
            blacklist.any { blocked -> voice.name.equals(blocked, true) }
        }
        val isRhVoice = packageName.orEmpty().contains("rhvoice", ignoreCase = true)
        if (!isRhVoice) return fromEngine.sortedBy { it.name }
        // У RHVoice getVoices() часто пуст — доузнаём каталоги вручную.
        val probed = installedRhVoices(engine, "ru") +
            installedRhVoices(engine, "en") +
            installedRhVoices(engine, "uk")
        return (fromEngine + probed)
            .distinctBy { it.name.lowercase(Locale.US) }
            .sortedBy { it.name }
    }

    /** Языки, реально представленные в списке голосов (для переключателя). */
    fun languagesIn(voices: List<Voice>): List<String> =
        voices.asSequence()
            .mapNotNull { it.locale?.language?.lowercase(Locale.US)?.takeIf(String::isNotBlank) }
            .distinct()
            .sorted()
            .toList()

    /**
     * Голоса для языка [language] (ISO-639-1). Handles ISO-2/ISO-3 locale
     * differences, lazy engines and an RHVoice-specific OEM fallback.
     */
    fun voicesFor(
        tts: TextToSpeech?,
        language: String,
        enginePackage: String? = null,
    ): List<Voice> {
        val engine = tts ?: return emptyList()
        val packageName = enginePackage?.takeIf { it.isNotBlank() }
            ?: runCatching { engine.defaultEngine }.getOrNull()
        val isRhVoice = packageName.orEmpty().contains("rhvoice", ignoreCase = true)
        val all = try {
            engine.voices.orEmpty()
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "voices() failed" }
            emptySet()
        }
        val filtered = all.filter { voice ->
            languageMatches(voice.locale, language) &&
                blacklist.none { blocked -> voice.name.equals(blocked, true) }
        }.sortedBy { it.name }
        if (isRhVoice) {
            val direct = filtered.filterNot {
                it.name.equals("Russian", true) || it.name.equals("English", true)
            }
            if (direct.size > 1) return direct
            val probed = installedRhVoices(engine, language)
            val merged = (direct + probed)
                .distinctBy { it.name.lowercase(Locale.US) }
                .sortedBy { it.name }
            if (merged.isNotEmpty()) return merged
        }
        if (filtered.isNotEmpty()) return filtered

        // Some engines expose only the currently loaded/default Voice while
        // getVoices() is empty. Keep these as a generic one-voice fallback.
        return buildList {
            runCatching { engine.voice }.getOrNull()?.let(::add)
            runCatching { engine.defaultVoice }.getOrNull()?.let(::add)
        }.distinctBy { it.name }
            .filter { languageMatches(it.locale, language) }
            .sortedBy { it.name }
    }

    private fun localeFor(language: String): Locale = when (language.lowercase(Locale.US)) {
        "ru" -> Locale("ru", "RU")
        "en" -> Locale.US
        "ja" -> Locale.JAPAN
        "ko" -> Locale.KOREA
        "zh" -> Locale.SIMPLIFIED_CHINESE
        "uk" -> Locale("uk", "UA")
        else -> Locale(language)
    }

    private fun languageMatches(locale: Locale, language: String): Boolean {
        val requested = language.lowercase(Locale.US).substringBefore('-').substringBefore('_')
        val accepted = languageAliases[requested] ?: setOf(requested)
        val actual = buildSet {
            add(locale.language.lowercase(Locale.US))
            runCatching { locale.isO3Language.lowercase(Locale.US) }.getOrNull()?.let(::add)
        }
        return actual.any { it in accepted }
    }

    /**
     * RHVoice's service accepts a Voice by exact name and returns ERROR for a
     * missing/disabled pack. This lets us recover the installed subset on OEM
     * firmware where Android loses the service's onGetVoices() response.
     */
    /** Local RHVoice catalog used by the settings UI and loopback HTTP API. */
    fun localCatalog(language: String): List<Voice> {
        val lang = language.lowercase(Locale.US)
        val locale = localeFor(lang)
        return rhVoiceCatalog[lang].orEmpty().map { name ->
            Voice(
                name,
                locale,
                Voice.QUALITY_NORMAL,
                Voice.LATENCY_NORMAL,
                false,
                emptySet(),
            )
        }
    }

    private fun installedRhVoices(tts: TextToSpeech, language: String): List<Voice> {
        val candidates = localCatalog(language)
        if (candidates.isEmpty()) return emptyList()
        val original = runCatching { tts.voice }.getOrNull()
        val accepted = candidates.filter { candidate ->
            runCatching { tts.setVoice(candidate) == TextToSpeech.SUCCESS }.getOrDefault(false)
        }
        if (original != null) {
            runCatching { tts.setVoice(original) }
        } else {
            runCatching { tts.setLanguage(localeFor(language)) }
        }
        // Several OEM TextToSpeech clients reject manually constructed Voice
        // objects before RHVoice sees them. The same names still work when sent
        // as Engine.KEY_PARAM_VOICE_NAME with speak(), so keep the local list.
        return accepted.ifEmpty { candidates }
    }

    /** Значащий сегмент имени Google-голоса: `ru-ru-x-dfc-local` -> `dfc`. */
    private fun googleCode(name: String): String? {
        val parts = name.lowercase(Locale.US).split('-')
        val xIndex = parts.indexOf("x")
        return if (xIndex >= 0 && xIndex + 1 < parts.size) parts[xIndex + 1] else null
    }

    fun classify(v: Voice): VoiceKind {
        val n = (v.name + " " + v.locale?.toLanguageTag().orEmpty()).lowercase(Locale.US)

        // 1) признак пола, объявленный самим движком
        val features = runCatching { v.features }.getOrNull().orEmpty()
        features.forEach { f ->
            val lf = f.lowercase(Locale.US)
            if (lf.contains("female")) return VoiceKind.FEMALE
            if (lf.contains("male")) return VoiceKind.MALE
        }

        // 2) явные подсказки в имени (Яндекс, RHVoice, Samsung)
        when {
            teenHints.any { n.contains(it) } -> return VoiceKind.TEEN
            // "female" содержит "male", поэтому женское проверяем первым
            femaleHints.any { n.contains(it) } -> return VoiceKind.FEMALE
            maleHints.any { n.contains(it) } -> return VoiceKind.MALE
        }

        // 3) таблица кодов Google Speech Services
        googleCode(v.name)?.let { code ->
            if (code in googleFemaleCodes) return VoiceKind.FEMALE
            if (code in googleMaleCodes) return VoiceKind.MALE
        }

        return VoiceKind.OTHER
    }

    /**
     * Голос для роли. Если движок не даёт распознать пол (частый случай для
     * Google-кодов вне таблицы), голоса всё равно РАЗВОДЯТСЯ: женским ролям
     * достаётся первый нераспознанный, мужским — следующий. Так в сцене
     * звучат разные голоса, даже когда пол формально неизвестен.
     */
    fun pick(
        tts: TextToSpeech?,
        kind: VoiceKind,
        exactName: String?,
        enginePackage: String? = null,
    ): Voice? = pickFor(tts, kind, exactName, "ru", enginePackage)

    fun pickFor(
        tts: TextToSpeech?,
        kind: VoiceKind,
        exactName: String?,
        language: String,
        enginePackage: String? = null,
    ): Voice? {
        val all = voicesFor(tts, language, enginePackage)
        if (all.isEmpty()) return null
        if (!exactName.isNullOrBlank()) all.find { it.name == exactName }?.let { return it }

        // Локальные голоса предпочтительнее сетевых: работают без интернета.
        val ranked = all.sortedWith(compareBy({ it.isNetworkConnectionRequired }, { it.name }))
        val group = ranked.filter { classify(it) == kind }
        if (group.isNotEmpty()) {
            val preferred = when (kind) {
                VoiceKind.FEMALE -> group.firstOrNull { it.name.contains("svetlana", true) }
                VoiceKind.MALE -> group.firstOrNull { it.name.contains("dmitr", true) }
                else -> null
            }
            return preferred ?: group.first()
        }

        // Пол не определён — разводим роли по разным голосам детерминированно.
        val unknown = ranked.filter { classify(it) == VoiceKind.OTHER }
        val pool = unknown.ifEmpty { ranked }
        val index = when (kind) {
            VoiceKind.FEMALE -> 0
            VoiceKind.MALE -> 1
            VoiceKind.TEEN -> 2
            VoiceKind.OTHER -> 0
        }
        return pool.getOrNull(index % pool.size) ?: pool.firstOrNull()
    }

    /**
     * Отдельный голос на говорящего: разные персонажи одного пола получают
     * разные голоса из своей группы (по кругу), чтобы диалог не звучал
     * одинаково. [speakerSlot] — порядковый номер персонажа в сцене.
     */
    fun pickForSpeaker(
        tts: TextToSpeech?,
        kind: VoiceKind,
        speakerSlot: Int,
        language: String = "ru",
        enginePackage: String? = null,
    ): Voice? {
        val all = voicesFor(tts, language, enginePackage)
        if (all.isEmpty()) return null
        val ranked = all.sortedWith(compareBy({ it.isNetworkConnectionRequired }, { it.name }))
        val group = ranked.filter { classify(it) == kind }
        val pool = when {
            group.isNotEmpty() -> group
            else -> ranked.filter { classify(it) == VoiceKind.OTHER }.ifEmpty { ranked }
        }
        if (pool.isEmpty()) return null
        val offset = if (group.isEmpty()) {
            when (kind) {
                VoiceKind.MALE -> 1
                VoiceKind.TEEN -> 2
                else -> 0
            }
        } else {
            0
        }
        return pool[(offset + speakerSlot.coerceAtLeast(0)) % pool.size]
    }
}

/**
 * ЛОКАЛЬНЫЙ AI-помощник выбора голосов (по запросу пользователя: «внутренний
 * json АИ помогает с выбором голосов локально»). Никакой сети: правила в
 * JSON-файле /sdcard/Yomikai/AI/voice_rules.json, который можно править
 * руками или попросить AI-агента (write_file/edit_file). Формат:
 * {
 *   "rules": [
 *     {"contains": "имя_персонажа", "voice": "имя-голоса-или-id"},
 *     {"gender": "female", "engine": "onnx", "voice": "irina"}
 *   ]
 * }
 * recommend() применяет правила к тексту реплики и полу говорящего.
 */
object LocalVoiceAdvisor {

    data class Advice(val voiceName: String?, val onnxVoiceId: String?)

    private fun rulesFile(): java.io.File =
        java.io.File(
            android.os.Environment.getExternalStorageDirectory(),
            "Yomikai/AI/voice_rules.json",
        )

    fun recommend(text: String, gender: String?): Advice {
        val f = rulesFile()
        if (!f.isFile) return Advice(null, null)
        return runCatching {
            val root = org.json.JSONObject(f.readText())
            val rules = root.optJSONArray("rules") ?: return Advice(null, null)
            for (i in 0 until rules.length()) {
                val r = rules.optJSONObject(i) ?: continue
                val contains = r.optString("contains")
                val g = r.optString("gender")
                val matches =
                    (contains.isNotBlank() && text.contains(contains, ignoreCase = true)) ||
                        (contains.isBlank() && g.isNotBlank() && g == gender)
                if (matches) {
                    val voice = r.optString("voice")
                    return if (r.optString("engine") == "onnx") {
                        Advice(null, voice.ifBlank { null })
                    } else {
                        Advice(voice.ifBlank { null }, null)
                    }
                }
            }
            Advice(null, null)
        }.getOrDefault(Advice(null, null))
    }

    /** Есть ли файл правил (для подсказки в UI). */
    fun hasRules(): Boolean = rulesFile().isFile
}

package eu.kanade.tachiyomi.data.tts

import android.content.Context
import android.speech.tts.TextToSpeech
import mihon.domain.ocr.service.OcrPreferences
import uy.kohesive.injekt.Injekt
import uy.kohesive.injekt.api.get

/**
 * Продвинутый резолвер голосов: 1 / 2 / 3 голоса.
 *
 * Запрос пользователя:
 *  - 1 голос — один нарратор (выбор муж/жен) озвучивает всё
 *  - 2 голоса — мужской и женский (локальный или онлайн) по полу реплики
 *  - 3 голоса — муж + жен + нарратор (отдельный выбор)
 *
 *Каждый из трёх слотов имеет свой движок:
 *  - `pref_voice_male_engine`  → male
 *  - `pref_voice_female_engine`→ female
 *  - `pref_voice_narrator_engine` → narrator
 *и свой голос внутри движка (`pref_voice_male`, `pref_voice_female`, `pref_voice_name` для нарратора).
 *
 * Логика [resolve] применяется в [TtsSpeaker.speakAs] и [AutoReadEngine].
 */
object VoiceModeResolver {

    enum class Mode(val id: String, val title: String, val desc: String) {
        SINGLE("single", "Один голос", "Весь текст — голосом нарратора"),
        DUAL("dual", "Два голоса", "Мужские реплики — мужским, женские — женским"),
        TRIPLE("triple", "Три голоса", "Муж + Жен + Нарратор (описания, ремарки)"),
        /** Много голосов: свой голос каждому персонажу одного пола в сцене. */
        MULTI("multi", "Много голосов", "Отдельный голос каждому персонажу одного пола"),
        ;

        companion object {
            fun fromId(id: String?): Mode = entries.firstOrNull { it.id == id } ?: DUAL
        }
    }

    data class ResolvedVoice(
        val gender: String, // male | female | narrator
        val engine: String, // system_tts | google_web | remote_tts | eleven_api
        val voiceName: String,
        val isLocal: Boolean,
        val isOnline: Boolean,
    )

    private fun prefs(): OcrPreferences = Injekt.get()

    fun currentMode(): Mode = Mode.fromId(prefs().voiceMode().get())

    fun narratorGender(): String = prefs().narratorGender().get().lowercase().let {
        when (it) {
            "male", "female" -> it
            else -> "female" // auto → female по умолчанию
        }
    }

    /**
     * Выбрать голос для реплики с учётом режима и пола, определённого
     * морфологией/AI (female/male/null).
     *
     * @param detectedGender пол реплики от RuMorph/AI: "female"|"male"|null
     * @param isNarration был ли текст помечен как нарратив (без кавычек, описания)
     */
    fun resolve(
        detectedGender: String?,
        isNarration: Boolean = false,
        speakerSlot: Int = 0,
    ): ResolvedVoice {
        val mode = currentMode()
        val p = prefs()

        return when (mode) {
            Mode.SINGLE -> {
                val g = narratorGender()
                val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                val name = when (g) {
                    "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                    else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                }
ResolvedVoice(
                    gender = g,
                    engine = engine,
                    voiceName = name,
                    isLocal = engine == TtsSpeaker.ENGINE_SYSTEM || engine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = engine == TtsSpeaker.ENGINE_GOOGLE_WEB || engine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.DUAL -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
            Mode.TRIPLE -> {
                if (isNarration) {
                    val g = narratorGender()
                    val engine = p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }
                    val name = when (g) {
                        "male" -> p.voiceMale().get().ifBlank { p.voiceName().get() }
                        else -> p.voiceFemale().get().ifBlank { p.voiceName().get() }
                    }
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                } else {
                    val g = detectedGender ?: "female"
                    val isMale = g == "male"
                    val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                    val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                    ResolvedVoice(g, engine.ifBlank { TtsSpeaker.ENGINE_SYSTEM }, name, true, false)
                }
            }
            // Много голосов: по полу, как DUAL; отдельные слоты персонажам
            // назначаются в AutoReadEngine (speakerSlot), здесь voice тот же.
            Mode.MULTI -> {
                val g = detectedGender ?: narratorGender()
                val isMale = g == "male"
                val engine = if (isMale) p.voiceMaleEngine().get() else p.voiceFemaleEngine().get()
                val fallbackEngine = p.voiceEngine().get()
                val effEngine = engine.ifBlank { fallbackEngine }
                val name = if (isMale) p.voiceMale().get() else p.voiceFemale().get()
                ResolvedVoice(
                    gender = g,
                    engine = effEngine.ifBlank { TtsSpeaker.ENGINE_SYSTEM },
                    voiceName = name,
                    isLocal = effEngine == TtsSpeaker.ENGINE_SYSTEM || effEngine == TtsSpeaker.ENGINE_REMOTE,
                    isOnline = effEngine == TtsSpeaker.ENGINE_GOOGLE_WEB || effEngine == TtsSpeaker.ENGINE_EDGE_TTS,
                )
            }
        }
    }

    fun describeCurrent(): String {
        val mode = currentMode()
        val p = prefs()
        return when (mode) {
            Mode.SINGLE -> "Один голос: нарратор ${narratorGender()} (${p.voiceNarratorEngine().get().ifBlank { p.voiceEngine().get() }})"
            Mode.DUAL -> "Два голоса: муж (${p.voiceMaleEngine().get().ifBlank { "system_tts" }}) + жен (${p.voiceFemaleEngine().get().ifBlank { "system_tts" }})"
            Mode.TRIPLE -> "Три голоса: муж (${p.voiceMaleEngine().get()}) + жен (${p.voiceFemaleEngine().get()}) + нарратор ${narratorGender()} (${p.voiceNarratorEngine().get()})"
            Mode.MULTI -> "Много голосов: отдельный голос каждому персонажу одного пола"
        }
    }

    /**
     * Применить resolved-голос к TextToSpeech: setVoice + rate/pitch от VoicePreset.
     */
    fun applyToTts(
        tts: TextToSpeech?,
        resolved: ResolvedVoice,
        rate: Float,
        pitch: Float,
    ) {
        if (tts == null) return
        val kind = when (resolved.gender) {
            "male" -> VoiceKind.MALE
            "female" -> VoiceKind.FEMALE
            else -> VoiceKind.OTHER
        }
        val voice = VoiceHelper.pickFor(tts, kind, resolved.voiceName.takeIf { it.isNotBlank() }, "ru", null)
        if (voice != null) {
            runCatching { tts.voice = voice }
        }
        tts.setSpeechRate(rate)
        tts.setPitch(pitch)
    }
}

package eu.kanade.tachiyomi.data.tts

/**
 * Самодельный ВСТРОЕННЫЙ AI-помощник озвучки. Никаких API-ключей и сети:
 * пол говорящего определяется лингвистической эвристикой прямо на устройстве.
 *
 * Для русского текста работает морфология:
 *  • глаголы прошедшего времени от первого лица: «сказала/подумала/пришла…»
 *    → женская реплика; «сказал/подумал/пришёл…» → мужская;
 *  • самоописания: «я рада», «я сама», «я готова» vs «я рад», «я сам»,
 *    «я готов»;
 *  • обращения-маркеры: «сестрёнка, ты…», «братик, ты…» относятся к
 *    собеседнику и НЕ учитываются для говорящего.
 *
 * Скоринг: считаем женские и мужские маркеры, отвечаем полом только при
 * явном перевесе — иначе null (нейтральный голос). Лучше промолчать, чем
 * озвучить неверным полом.
 */
object LocalSpeakerAi {

    // «я/мне/меня …-ла» — окончание прошедшего времени ж.р.
    private val feminineVerb = Regex("""(?:^|\s)(?:я|ведь я|и я)\s+(?:\S+\s+){0,2}?\S+ла(?:сь)?\b""")
    private val masculineVerb = Regex("""(?:^|\s)(?:я|ведь я|и я)\s+(?:\S+\s+){0,2}?\S+(?:[^аеиоуыэюяль]|ёл|ел|ал|ул|ил|ыл|л)(?:ся)?\b""")

    private val feminineSelf = listOf(
        "я сама", "я рада", "я готова", "я должна", "я уверена", "я согласна",
        "я не могла", "я была", "я хотела", "я думала", "я поняла", "я знала",
        "я видела", "я слышала", "я пришла", "я решила", "сама справлюсь",
        "я устала", "я испугалась", "я замужем",
        // самоидентификация через существительные
        "я мама", "я мать", "я сестра", "я дочь", "я бабушка", "я девушка",
        "я женщина", "я принцесса", "я королева", "я ведьма", "я учительница",
        // самоидентификация через прилагательные
        "я красивая", "я сильная", "я умная", "я добрая", "я злая",
        "я беременна", "я влюблена", "я свободна", "я занята", "я права",
    )
    private val masculineSelf = listOf(
        "я сам", "я рад", "я готов", "я должен", "я уверен", "я согласен",
        "я не мог", "я был", "я хотел", "я думал", "я понял", "я знал",
        "я видел", "я слышал", "я пришёл", "я пришел", "я решил", "сам справлюсь",
        "я устал", "я испугался", "я женат",
        // самоидентификация через существительные
        "я папа", "я отец", "я брат", "я сын", "я дед", "я мужчина", "я парень",
        "я юноша", "я принц", "я король", "я воин", "я рыцарь", "я маг",
        // самоидентификация через прилагательные
        "я красивый", "я сильный", "я умный", "я добрый", "я злой",
        "я свободен", "я занят", "я прав", "я виноват",
    )

    /** Пол говорящего: "female" | "male" | null (не уверены). */
    fun guessGender(rawText: String): String? {
        val text = " " + rawText.lowercase().replace('ё', 'ё') + " "

        var female = 0
        var male = 0

        for (marker in feminineSelf) if (text.contains(marker)) female += 2
        for (marker in masculineSelf) if (text.contains(marker)) male += 2

        if (feminineVerb.containsMatchIn(text)) female += 1
        else if (masculineVerb.containsMatchIn(text)) male += 1

        return when {
            female > male -> "female"
            male > female -> "male"
            else -> null
        }
    }

    /**
     * Пол для каждой реплики кадра. Реплики без явных маркеров наследуют
     * пол предыдущей уверенной реплики того же кадра только если стоят
     * вплотную (диалог одного персонажа из нескольких бабблов подряд).
     */
    fun guessGenders(lines: List<String>): List<String?> {
        val result = arrayOfNulls<String>(lines.size)
        for (i in lines.indices) {
            result[i] = guessGender(lines[i])
        }
        return result.toList()
    }
}

package eu.kohesive.tachiyomi.data.tts

/**
 * Плагин синтеза речи для звуков, которые обычный голос произнести не
 * умеет: вздох, вдох, стон, крик, смех, кашель. Обычный движок в лучшем
 * случае читает их буквами («А-а-а...»), и погружение от этого ломается.
 *
 * Плагин необязателен: читатель сам решает, нужен ли ему такой слой звука.
 * Пока плагин выключен или не скачан, звуки идут в голос как раньше — то
 * есть мост не меняет поведение приложения, пока его не включили явно.
 *
 * Вариантов несколько, у каждого свой помощник ([helperHint]): «помощник» —
 * это агент из доступных провайдеров, который помогает настроить именно
 * этот вариант (подобрать голос, подготовить образцы, объяснить, что
 * делать). Выбор варианта и выбор помощника — разные вещи: звук играет
 * всегда локально, а помогает ему кто может.
 */
object TtsPluginBridge {

    /** Вариант синтеза звука. */
    enum class Variant(
        val id: String,
        val title: String,
        /** Нужен интернет при первом получении звука; дальше работает из кэша. */
        val needsNetwork: Boolean,
        /** Признак, что вариант умеет играть звук на этом устройстве. */
        val playable: Boolean,
    ) {
        /**
         * Звук генерирует провайдер из настроек и кэшируется локально. Работает
         * сразу, без файлов от пользователя, поэтому это стартовый вариант.
         */
        AI_CACHED(
            id = "ai_cached",
            title = "AI-звук (с кэшем)",
            needsNetwork = true,
            playable = true,
        ),

        /**
         * Готовые образцы звуков, скачиваемые пакетом. Мгновенно, офлайн и
         * почти не грузит процессор, но включается только когда пакет есть на
         * устройстве: сам комплект звуков не создаётся и не выдумывается.
         */
        AUDIO_PACK(
            id = "audio_pack",
            title = "Аудиопак (офлайн)",
            needsNetwork = false,
            playable = true,
        ),

        /**
         * Голос читателя: нарезка из своего аудио/видео или чужого, с
         * привязкой как TTS-голос. Требует провайдера с клонированием.
         */
        CUSTOM_VOICE(
            id = "custom_voice",
            title = "Свой голос",
            needsNetwork = true,
            playable = true,
        );

        companion object {
            fun of(id: String?): Variant? = entries.firstOrNull { it.id == id }
        }
    }

    /** Что делает мост с куском реплики. */
    enum class Action {
        /** Обычный голос: это текст или междометие, либо плагин выключен. */
        VOICE,

        /** Плагин: настоящий звук, который голос не умеет. */
        PLUGIN,

        /** Плагин включён, но звук он отдать не смог — голосом. */
        VOICE_FALLBACK,
    }

    /**
     * Решение моста по одному куску реплики.
     *
     * Правило намеренно простое: плагин забирает только то, что он умеет
     * ([SpeechCue.Delivery.isSound]), и только когда он реально готов. Любой
     * сбой плагина — это откат на голос, а не пропавший звук.
     */
    fun decide(
        isSound: Boolean,
        variant: Variant?,
        downloaded: Boolean,
        enabled: Boolean,
    ): Action = when {
        !enabled -> Action.VOICE
        variant == null -> Action.VOICE
        !downloaded -> Action.VOICE
        !variant.playable -> Action.VOICE
        !isSound -> Action.VOICE
        else -> Action.PLUGIN
    }

    /** Уже включённый вариант или null, если плагин выключен/не скачан. */
    fun activeVariant(
        variantId: String?,
        downloaded: Boolean,
        enabled: Boolean,
    ): Variant? = if (enabled && downloaded) Variant.of(variantId) else null

    /**
     * Следующий вариант по кругу — «кому какой больше понравится»: читатель
     * щёлкает кнопкой и слушает, ничего не настраивая. Выключенный плагин
     * включается первым вариантом, из конца — снова выключается.
     */
    fun nextVariant(currentId: String?, enabled: Boolean): String? {
        val order = Variant.entries.map { it.id }
        if (!enabled) return order.first()
        val index = order.indexOf(Variant.of(currentId)?.id ?: order.last())
        return if (index < 0) order.first() else order[(index + 1) % order.size]
    }
}

