            val voiceMatchesGender = v != null && when (gender) {
                "male" -> VoiceHelper.classify(v) == VoiceKind.MALE
                "female" -> VoiceHelper.classify(v) == VoiceKind.FEMALE
                else -> true
            }
            val genderPitchMod = when {
                voiceMatchesGender -> 1.0f
                gender == "male" -> 0.78f
