                        // v1.9.44: hidden-параметр «voiceName» ломает speak() на RHVoice
                        // (голос уже задан через setVoice() выше) — Bundle не шлём.
                        val r = runCatching {
                            engine.speak(
                                "Привет! Это тест голоса $voiceName.",
                                TextToSpeech.QUEUE_FLUSH,
                                null,
                                "yk_vtest",
                            )
                        }.getOrDefault(TextToSpeech.ERROR)
                        if (r != TextToSpeech.SUCCESS) setSpeaking(false)
                    }
                }
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "voice test failed" }
                setSpeaking(false)
            }
        }
    }

    // region REMOTE (нейроголоса на сервере ПК/ранера)

    /**
     * УДАЛЁННЫЙ НЕЙРОГОЛОС: sherpa-onnx/Piper больше не живёт в APK (R8, ABI и
     * память устройства ломали синтез). Синтез крутится на ПК пользователя или
     * сервере (tools/remote_tts_server.py): приложение шлёт предложение и
     * проигрывает готовый wav. Нет адреса или сервер молчит — дочитываем
     * системным голосом (принцип AlReader: текст всегда озвучен).
     */
    private fun speakRemote(context: Context, text: String, gender: String?) {
        val p = prefs()
        currentJob = scope.launch {
            setSpeaking(true)
            val url = p.remoteTtsUrl().get().trim()
            // Предложения разворачиваются в куски с подачей, чтобы «ааа» и
            // вздох из ремарки ушли отдельным запросом со своим темпом.
            val sentences = splitSentences(text).flatMap { splitForRemote(it) }
            if (url.isBlank()) {
                withContext(Dispatchers.Main) { speakSystem(context, text, gender) }
                return@launch
            }
            var doneUpTo = 0
            var failed = false
            try {
                for (sentence in sentences) {
                    if (currentJob?.isActive != true) break
                    val trimmed = sentence.text.trim()
                    val wav = synthesizeRemote(context, url, trimmed, gender, sentence.rate)
                    if (wav == null) {
                        failed = true
                        break
                    }
                    playFileBlocking(wav)
                    doneUpTo++
                    kotlinx.coroutines.delay(180L)
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                setSpeaking(false)
                throw e
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "remote TTS failed" }
                failed = true
            }
            if (failed && doneUpTo < sentences.size && currentJob?.isActive == true) {
                val rest = sentences.drop(doneUpTo).joinToString(" ") { it.text }
                logcat(LogPriority.WARN) { "remote TTS fallback to system from sentence $doneUpTo" }
                withContext(Dispatchers.Main) { speakSystem(context, rest, gender) }
            } else {
                setSpeaking(false)
            }
        }
    }

    /** Кусок для удалённого движка: текст и множитель темпа. */
    private class RemoteChunk(val text: String, val rate: Float)

    /**
     * Разворачивает предложение в куски для удалённого движка. Разбиение
     * общее с системным ([SpeechCue.deliveries]), но темп передаётся в
     * параметре `speed` запроса, потому что у сервера нет сетевого тона.
     */
    private fun splitForRemote(sentence: String): List<RemoteChunk> {
        val trimmed = sentence.trim()
        if (trimmed.isEmpty()) return emptyList()
        return SpeechCue.deliveries(trimmed).map { RemoteChunk(it.text, it.rate) }
    }

    /** POST {text, voice, speed} на /tts сервера; ответ — wav-байты. */
    private suspend fun synthesizeRemote(
        context: Context,
        url: String,
        text: String,
        gender: String?,
        rateFactor: Float = 1f,
    ): File? = withContext(Dispatchers.IO) {
        runCatching {
            val conn = java.net.URL(url.trimEnd('/') + "/tts").openConnection()
                as java.net.HttpURLConnection
            conn.connectTimeout = 5_000
            conn.readTimeout = 90_000
            conn.requestMethod = "POST"
            conn.doOutput = true
            conn.setRequestProperty("Content-Type", "application/json")
            val speed = (prefs().speechRate().get() * rateFactor).coerceIn(0.5f, 2f)
            val body = "{\"text\":${jsonQuote(text)},\"voice\":${jsonQuote(gender ?: "auto")},\"speed\":$speed}"
            conn.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }
            if (conn.responseCode != 200) {
                logcat(LogPriority.WARN) { "remote TTS HTTP ${conn.responseCode}" }
                return@runCatching null
            }
            val dir = File(context.cacheDir, "remote_tts").apply { mkdirs() }
            val f = File(dir, "seg_${System.currentTimeMillis()}.wav")
            conn.inputStream.use { input -> f.outputStream().use { input.copyTo(it) } }
            if (f.length() < 1024) {
                f.delete()
                null
            } else {
                f
            }
        }.getOrNull()
    }

    // endregion

    // region GOOGLE WEB (без API-ключа)

    private fun speakGoogleWeb(context: Context, text: String) {
        val lang = prefs().ttsWebLanguage().get().ifBlank { "ru" }
        currentJob = scope.launch {
            setSpeaking(true)
            try {
                // Endpoint сайта Google Translate ограничен ~200 симв. — бьём на куски
                val chunks = splitForWeb(text, 180)
                for (chunk in chunks) {
                    if (currentJob?.isActive != true) break
                    val url = "https://translate.google.com/translate_tts" +
                        "?ie=UTF-8&client=tw-ob&tl=" + lang +
                        "&q=" + URLEncoder.encode(chunk, "UTF-8")
                    val file = downloadToCache(context, url) ?: continue
                    playFileBlocking(file)
                }
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "Google Web TTS failed" }
            } finally {
                setSpeaking(false)
            }
        }
    }

    // endregion

    // region EDGE TTS (Microsoft, без ключа)

    /**
     * Озвучка онлайн-голосами Microsoft Edge (edge-tts). Бесплатно, без
     * API-ключа, нужен интернет. Выбранный голос — pref_edge_voice; если
     * редактором выбран мультиязычный голос, он читает любой язык.
     * Скорость/высота берутся из обычных настроек озвучки.
     */
    private fun speakEdgeTts(context: Context, text: String, voiceName: String? = null) {
        val p = prefs()
        val voice = voiceName?.takeIf { it.isNotBlank() }
            ?: p.edgeVoice().get().ifBlank { EdgeTts.DEFAULT_VOICE }
        val ratePercent = ((p.speechRate().get().coerceIn(0.5f, 2f) - 1f) * 100).toInt().coerceIn(-50, 100)
        val pitchHz = ((p.speechPitch().get().coerceIn(0.5f, 2f) - 1f) * 40).toInt().coerceIn(-50, 50)
        currentJob = scope.launch {
            var delegated = false
            setSpeaking(true)
            try {
                val file = EdgeTts.synthesizeToFile(
                    context = context,
                    text = text,
                    voice = voice,
                    ratePercent = ratePercent,
                    pitchHz = pitchHz,
                    useCache = true,
                )
                if (file == null) {
                    delegated = true
                    withContext(Dispatchers.Main) { speakSystem(context, text) }
                } else {
                    playFileBlocking(file, deleteAfterPlayback = false)
                }
            } catch (e: kotlinx.coroutines.CancellationException) {
                throw e
            } catch (e: Exception) {
                delegated = true
                logcat(LogPriority.WARN, e) { "Edge TTS failed; using system voice" }
                withContext(Dispatchers.Main) { speakSystem(context, text) }
            } finally {
                if (!delegated) setSpeaking(false)
            }
        }
    }

    /** Проба конкретного голоса Edge TTS (кнопка «Проба» в списке голосов). */
    fun speakEdgeVoiceTest(context: Context, voice: String, onDone: () -> Unit = {}) {
        stop()
        currentJob = scope.launch {
            setSpeaking(true)
            try {
                val p = prefs()
                val file = EdgeTts.synthesizeToFile(
                    context = context,
                    text = "Привет! Это тест голоса $voice.",
                    voice = voice.ifBlank { EdgeTts.DEFAULT_VOICE },
                    ratePercent = ((p.speechRate().get().coerceIn(0.5f, 2f) - 1f) * 100)
                        .toInt().coerceIn(-50, 100),
                    pitchHz = ((p.speechPitch().get().coerceIn(0.5f, 2f) - 1f) * 40)
                        .toInt().coerceIn(-50, 50),
                    useCache = true,
                )
                if (file != null) {
                    playFileBlocking(file, deleteAfterPlayback = false)
                } else {
                    setSpeaking(false)
                }
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "Edge voice test failed" }
                setSpeaking(false)
            } finally {
                onDone()
            }
        }
    }

    // endregion

    // region ELEVENLABS (API-ключ)

    private fun speakElevenLabs(context: Context, text: String) {
        val p = prefs()
        val apiKey = p.elevenApiKey().get()
        if (apiKey.isBlank()) {
            // Ключа нет — честный фолбэк на бесплатную веб-озвучку
            speakGoogleWeb(context, text)
            return
        }
        val voiceId = p.elevenVoiceId().get().ifBlank { "21m00Tcm4TlvDq8ikWAM" }
        currentJob = scope.launch {
            setSpeaking(true)
            try {
                val conn = URL("https://api.elevenlabs.io/v1/text-to-speech/$voiceId")
                    .openConnection() as HttpURLConnection
                conn.requestMethod = "POST"
                conn.doOutput = true
                conn.connectTimeout = 20_000
                conn.readTimeout = 60_000
                conn.setRequestProperty("xi-api-key", apiKey)
                conn.setRequestProperty("Content-Type", "application/json")
                conn.setRequestProperty("Accept", "audio/mpeg")
                val body = """{"text":${jsonQuote(text)},"model_id":"eleven_multilingual_v2"}"""
                conn.outputStream.use { it.write(body.toByteArray()) }
                if (conn.responseCode in 200..299) {
                    val file = File(context.cacheDir, "tts_eleven.mp3")
                    conn.inputStream.use { input -> file.outputStream().use { input.copyTo(it) } }
                    playFileBlocking(file)
                } else {
                    logcat(LogPriority.WARN) { "ElevenLabs HTTP ${conn.responseCode}" }
                    speakGoogleWebInline(context, text)
                }
                conn.disconnect()
            } catch (e: Exception) {
                logcat(LogPriority.WARN, e) { "ElevenLabs TTS failed" }
                speakGoogleWebInline(context, text)
            } finally {
                setSpeaking(false)
            }
        }
    }

    /** Фолбэк внутри уже запущенной корутины. */
    private suspend fun speakGoogleWebInline(context: Context, text: String) {
        val lang = prefs().ttsWebLanguage().get().ifBlank { "ru" }
        for (chunk in splitForWeb(text, 180)) {
            val url = "https://translate.google.com/translate_tts" +
                "?ie=UTF-8&client=tw-ob&tl=" + lang +
                "&q=" + URLEncoder.encode(chunk, "UTF-8")
            val file = downloadToCache(context, url) ?: continue
            playFileBlocking(file)
        }
    }

    // endregion

    // region helpers

    /**
     * Реальный список голосов аккаунта ElevenLabs (GET /v1/voices по ключу).
     * Возвращает пары (voice_id, имя + категория). Пустой список при ошибке
     * или отсутствии ключа — никаких фейковых данных.
     */
    suspend fun fetchElevenVoices(apiKey: String): List<Pair<String, String>> = withContext(Dispatchers.IO) {
        if (apiKey.isBlank()) return@withContext emptyList()
        runCatching {
            val conn = URL("https://api.elevenlabs.io/v1/voices").openConnection() as HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            conn.setRequestProperty("xi-api-key", apiKey)
            if (conn.responseCode !in 200..299) {
                logcat(LogPriority.WARN) { "ElevenLabs voices HTTP ${conn.responseCode}" }
                conn.disconnect()
                return@runCatching emptyList()
            }
            val body = conn.inputStream.bufferedReader().readText()
            conn.disconnect()
            val arr = org.json.JSONObject(body).optJSONArray("voices") ?: return@runCatching emptyList()
            buildList {
                for (i in 0 until arr.length()) {
                    val v = arr.optJSONObject(i) ?: continue
                    val id = v.optString("voice_id")
                    if (id.isBlank()) continue
                    val name = v.optString("name").ifBlank { id }
                    val labels = v.optJSONObject("labels")
                    val extra = buildList {
                        labels?.optString("gender")?.takeIf { it.isNotBlank() }?.let(::add)
                        labels?.optString("accent")?.takeIf { it.isNotBlank() }?.let(::add)
                        v.optString("category").takeIf { it.isNotBlank() }?.let(::add)
                    }.joinToString(", ")
                    add(id to if (extra.isBlank()) name else "$name ($extra)")
                }
            }
        }.getOrElse {
            logcat(LogPriority.WARN, it) { "ElevenLabs voices fetch failed" }
            emptyList()
        }
    }

    private fun jsonQuote(s: String): String {
        val sb = StringBuilder("\"")
        for (c in s) {
            when (c) {
                '"' -> sb.append("\\\"")
                '\\' -> sb.append("\\\\")
                '\n' -> sb.append("\\n")
                '\r' -> sb.append("\\r")
                '\t' -> sb.append("\\t")
                else -> sb.append(c)
            }
        }
        return sb.append('"').toString()
    }

    /** Делит текст на предложения по .!?…; куски без знаков — по 200 симв. */
    fun splitSentences(text: String): List<String> {
        val result = mutableListOf<String>()
        val sb = StringBuilder()
        for (ch in text) {
            sb.append(ch)
            if (ch == '.' || ch == '!' || ch == '?' || ch == '…' || ch == '‼' || ch == '⁇') {
                if (sb.isNotBlank()) result += sb.toString()
                sb.clear()
            } else if (sb.length >= 200 && ch == ' ') {
                result += sb.toString()
                sb.clear()
            }
        }
        if (sb.isNotBlank()) result += sb.toString()

        // Страховка: TextToSpeech.speak() бросает IllegalArgumentException,
        // если строка длиннее getMaxSpeechInputLength() (обычно 4000).
        // Текст без знаков препинания и без пробелов не резался ничем выше.
        return result.flatMap { it.chunked(HARD_UTTERANCE_LIMIT) }
    }

    private fun splitForWeb(text: String, max: Int): List<String> {
        if (text.length <= max) return listOf(text)
        val parts = mutableListOf<String>()
        var rest = text.trim()
        while (rest.isNotEmpty()) {
            if (rest.length <= max) { parts += rest; break }
            var cut = rest.lastIndexOfAny(charArrayOf('.', '!', '?', '…', ';'), max)
            if (cut < max / 2) cut = rest.lastIndexOf(' ', max)
            if (cut < max / 2) cut = max
            parts += rest.substring(0, cut + 1).trim()
            rest = rest.substring(cut + 1).trim()
        }
        return parts.filter { it.isNotBlank() }
    }

    private fun downloadToCache(context: Context, url: String): File? {
        return try {
            val conn = URL(url).openConnection() as HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            // Без браузерного UA endpoint отдаёт 403
            conn.setRequestProperty(
                "User-Agent",
                "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36",
            )
            if (conn.responseCode !in 200..299) {
                conn.disconnect()
                return null
            }
            val file = File(context.cacheDir, "tts_web_${System.nanoTime()}.mp3")
            conn.inputStream.use { input -> file.outputStream().use { input.copyTo(it) } }
            conn.disconnect()
            file
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "TTS download failed" }
            null
        }
    }

    private suspend fun playFileBlocking(
        file: File,
        deleteAfterPlayback: Boolean = true,
    ) {
        withContext(Dispatchers.IO) {
            suspendCancellableCoroutine { cont ->
                val mp = MediaPlayer()
                mediaPlayer = mp
                try {
                    mp.setDataSource(file.absolutePath)
                    mp.setOnCompletionListener {
                        runCatching { mp.release() }
                        if (deleteAfterPlayback) file.delete()
                        if (cont.isActive) cont.resume(Unit)
                    }
                    mp.setOnErrorListener { _, _, _ ->
                        runCatching { mp.release() }
                        if (deleteAfterPlayback) file.delete()
                        if (cont.isActive) cont.resume(Unit)
                        true
                    }
                    mp.prepare()
                    mp.start()
                    cont.invokeOnCancellation {
                        runCatching { mp.stop(); mp.release() }
                        if (deleteAfterPlayback) file.delete()
                    }
                } catch (e: Exception) {
                    runCatching { mp.release() }
                    if (deleteAfterPlayback) file.delete()
                    if (cont.isActive) cont.resume(Unit)
                }
            }
        }
    }

    // endregion
}

package eu.kanade.tachiyomi.data.voice

import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.os.Build
import android.speech.tts.TextToSpeech
import eu.kanade.tachiyomi.data.tts.TtsSpeaker
import eu.kanade.tachiyomi.data.tts.VoiceHelper
import eu.kanade.tachiyomi.data.tts.VoiceKind
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import logcat.LogPriority
import mihon.domain.ocr.service.OcrPreferences
import tachiyomi.core.common.util.system.logcat

/**
 * Тип голосового бэкенда. Совпадает со значениями `pref_voice_engine`
 * ("system_tts", "google_web", "eleven_api") и расширяется локальными
 * нейросетевыми движками, которые раньше выбирались отдельными настройками.
 */
/**
 * Id совпадают с константами [TtsSpeaker], потому что именно эти строки
 * сохраняются в `pref_voice_engine` и именно по ним [TtsSpeaker.speakAs]
 * выбирает, чем озвучивать реплику.
 *
 * Раньше ONNX был объявлен как `"onnx"`, а весь UI писал `"onnx_tts"`. Из-за
 * этого расхождения реестр считал выбранным системный TTS, а выбор ONNX в
 * настройках плагинов сохранял значение, которое маршрутизатор озвучки не
 * знал, — реплика молча уходила в системный голос.
 */
enum class VoiceBackend(val id: String) {
    /** Системные и сторонние Android TTS-движки. */
    SYSTEM_TTS(TtsSpeaker.ENGINE_SYSTEM),

    /** Веб-озвучка Google Translate: без ключа, но нужен интернет. */
    GOOGLE_WEB(TtsSpeaker.ENGINE_GOOGLE_WEB),

    /** Онлайн-голоса Microsoft Edge (edge-tts): без ключа, нужен интернет. */
    EDGE_TTS(TtsSpeaker.ENGINE_EDGE_TTS),

    /** ElevenLabs по API-ключу. */
    ELEVEN_API(TtsSpeaker.ENGINE_ELEVENLABS),

    /** Нейроголоса на сервере пользователя (ПК/ранер): sherpa-onnx + Piper. */
    REMOTE_TTS(TtsSpeaker.ENGINE_REMOTE),
    ;

    companion object {
        /** Значения из сборок, где ONNX ещё был объявлен как `onnx`. */
        private val LEGACY_IDS = mapOf(
            "onnx" to REMOTE_TTS,
            "onnx_tts" to REMOTE_TTS,
        )

        /**
         * Точное распознавание id, включая legacy-написания. `null`, если
         * значение не соответствует ни одному движку — в отличие от [fromId]
         * здесь нет молчаливого отката, поэтому `byId()` не обязан выдавать
         * системный плагин на любой мусор.
         */
        fun matchOrNull(id: String?): VoiceBackend? {
            val key = id?.trim().orEmpty()
            if (key.isEmpty()) return null
            return entries.firstOrNull { it.id == key } ?: LEGACY_IDS[key]
        }

        fun fromId(id: String?): VoiceBackend = matchOrNull(id) ?: SYSTEM_TTS
    }
}

/** Что нужно движку, чтобы озвучить реплику. */
enum class VoiceRequirement {
    /** Нужен интернет. */
    NETWORK,

    /** Нужен API-ключ. */
    API_KEY,

    /** Нужен установленный в системе Android TTS-движок. */
    SYSTEM_ENGINE,

    /** Нужно скачать модель голоса. */
    MODEL_DOWNLOAD,

    /** Нужна нативная библиотека, которой может не быть в сборке. */
    NATIVE_LIBRARY,

    /** Нужен адрес локального сервера озвучки (ПК/ранер). */
    SERVER_ADDRESS,
}

/**
 * Описание одного голосового движка как плагина.
 *
 * Как и [eu.kanade.tachiyomi.data.ai.AiPlugins], это декларативный реестр: он
 * ничего не озвучивает сам. Реальные вызовы остаются в `TtsSpeaker` и
 * `VoiceHelper`, а реестр даёт настройкам единый список движков с
 * понятными требованиями и списком голосов.
 */
data class VoicePluginDescriptor(
    val id: String,
    val backend: VoiceBackend,
    val title: String,
    val summary: String,
    val requirements: Set<VoiceRequirement> = emptySet(),
    /** Движок умеет разводить реплики по полу говорящего. */
    val supportsGender: Boolean = false,
    /** Движок умеет несколько разных голосов одновременно. */
    val supportsMultipleVoices: Boolean = false,
    /** Движок работает без сети. */
    val offline: Boolean = true,
)

/**
 * Реестр голосовых плагинов и один голос внутри них.
 *
 * [voices] намеренно функция, а не поле: список системных голосов зависит от
 * устройства и меняется во время работы приложения.
 */
/** голоса серверного синтеза: те же Piper-модели, что раньше качались в APK. */
private val REMOTE_VOICE_CATALOG = listOf(
    Triple("irina", "Ирина (женский, мягкий)", "female"),
    Triple("dmitri", "Дмитрий (мужской)", "male"),
    Triple("ruslan", "Руслан (мужской, низкий)", "male"),
)

object VoicePlugins {

    /** id серверных голосов — для настроек и контрактов (тесты). */
    val REMOTE_VOICE_CATALOG_IDS = REMOTE_VOICE_CATALOG.map { it.first }


    /** Один конкретный голос внутри движка. */
    data class Voice(
        val id: String,
        val name: String,
        /** female | male | neutral. */
        val gender: String,
        /** Язык в теге BCP-47, если движок его знает. */
        val language: String? = null,
        /** Размер модели в МБ, если голос нужно скачивать. */
        val sizeMb: Int = 0,
        /**
         * Готов ли голос к работе прямо сейчас. Для ONNX это реальная проверка
         * распакованной модели на диске, поэтому список не обещает голосов,
         * которых на устройстве нет.
         */
        val installed: Boolean = true,
    )

    val SYSTEM_TTS = VoicePluginDescriptor(
        id = VoiceBackend.SYSTEM_TTS.id,
        backend = VoiceBackend.SYSTEM_TTS,
        title = "Системный TTS",
        summary = "Голоса установленных Android-движков (Google, RHVoice, Acapela и любые другие).",
        requirements = setOf(VoiceRequirement.SYSTEM_ENGINE),
        supportsGender = true,
        supportsMultipleVoices = true,
    )

    val GOOGLE_WEB = VoicePluginDescriptor(
        id = VoiceBackend.GOOGLE_WEB.id,
        backend = VoiceBackend.GOOGLE_WEB,
        title = "Google Web (без ключа)",
        summary = "Веб-озвучка Google Translate: работает без API-ключа, но требует интернет.",
        requirements = setOf(VoiceRequirement.NETWORK),
        offline = false,
    )

    val EDGE_TTS = VoicePluginDescriptor(
        id = VoiceBackend.EDGE_TTS.id,
        backend = VoiceBackend.EDGE_TTS,
        title = "Edge TTS (без ключа)",
        summary = "Онлайн-голоса Microsoft Edge: ~300 голосов, включая мультиязычные. Без API-ключа.",
        requirements = setOf(VoiceRequirement.NETWORK),
        supportsMultipleVoices = true,
        offline = false,
    )

    val ELEVEN_API = VoicePluginDescriptor(
        id = VoiceBackend.ELEVEN_API.id,
        backend = VoiceBackend.ELEVEN_API,
        title = "ElevenLabs",
        summary = "Нейросетевая озвучка по API-ключу ElevenLabs.",
        requirements = setOf(VoiceRequirement.NETWORK, VoiceRequirement.API_KEY),
        supportsMultipleVoices = true,
        offline = false,
    )

    val REMOTE_TTS = VoicePluginDescriptor(
        id = VoiceBackend.REMOTE_TTS.id,
        backend = VoiceBackend.REMOTE_TTS,
        title = "TTS-сервер (ПК/ранер)",
        summary = "sherpa-onnx и русские Piper-голоса на вашей машине: приложение шлёт текст и проигрывает wav.",
        requirements = setOf(VoiceRequirement.SERVER_ADDRESS),
        supportsGender = true,
        supportsMultipleVoices = true,
        offline = false,
    )

    val ALL = listOf(SYSTEM_TTS, GOOGLE_WEB, EDGE_TTS, ELEVEN_API, REMOTE_TTS)

    private val BY_ID = ALL.associateBy { it.id }

    /**
     * Поиск плагина по сохранённому значению `pref_voice_engine`. Проходит
     * через [VoiceBackend.matchOrNull], поэтому legacy-запись `"onnx"` из
     * старых сборок находит тот же плагин, что и `"onnx_tts"`.
     */
    fun byId(id: String?): VoicePluginDescriptor? =
        VoiceBackend.matchOrNull(id)?.let { backend -> BY_ID[backend.id] }

    fun byBackend(backend: VoiceBackend): VoicePluginDescriptor? =
        ALL.firstOrNull { it.backend == backend }

    /** Движки, готовые к работе прямо сейчас. */
    fun available(
        networkAvailable: Boolean,
        systemEnginePresent: Boolean,
        hasApiKey: (VoicePluginDescriptor) -> Boolean = { false },
        nativeLibraryPresent: (VoicePluginDescriptor) -> Boolean = { true },
        modelsDownloaded: (VoicePluginDescriptor) -> Boolean = { false },
        hasServerAddress: (VoicePluginDescriptor) -> Boolean = { false },
    ): List<VoicePluginDescriptor> = ALL.filter { plugin ->
        plugin.requirements.all { requirement ->
            when (requirement) {
                VoiceRequirement.NETWORK -> networkAvailable
                VoiceRequirement.API_KEY -> hasApiKey(plugin)
                VoiceRequirement.SYSTEM_ENGINE -> systemEnginePresent
                VoiceRequirement.MODEL_DOWNLOAD -> modelsDownloaded(plugin)
                VoiceRequirement.NATIVE_LIBRARY -> nativeLibraryPresent(plugin)
                VoiceRequirement.SERVER_ADDRESS -> hasServerAddress(plugin)
            }
        }
    }

    /**
     * Голоса движка: системные берутся из настроек, серверные — из
     * каталога Piper-голосов ранера/ПК.
     */
    fun voices(context: Context, plugin: VoicePluginDescriptor, prefs: OcrPreferences): List<Voice> =
        when (plugin.backend) {
            VoiceBackend.REMOTE_TTS -> REMOTE_VOICE_CATALOG.map { voice ->
                Voice(
                    id = voice.first,
                    name = voice.second,
                    gender = voice.third,
                    language = "ru-RU",
                    installed = true,
                )
            }

            VoiceBackend.SYSTEM_TTS -> systemVoiceSources(prefs)

            VoiceBackend.EDGE_TTS -> listOf(
                prefs.edgeVoice().get().ifBlank { eu.kanade.tachiyomi.data.tts.EdgeTts.DEFAULT_VOICE }
            ).map { id ->
                Voice(
                    id = id,
                    name = "Edge TTS: $id",
                    gender = if (id.contains("Female")) "female" else if (id.contains("Male")) "male" else "neutral",
                )
            }

            VoiceBackend.ELEVEN_API -> listOfNotNull(
                prefs.elevenVoiceId().get().takeIf(String::isNotBlank)?.let {
                    Voice(id = it, name = "Голос ElevenLabs", gender = "neutral")
                },
            )

            VoiceBackend.GOOGLE_WEB -> listOf(
                Voice(
                    id = prefs.ttsWebLanguage().get().ifBlank { "ru" },
                    name = "Веб-голос ${prefs.ttsWebLanguage().get().ifBlank { "ru" }}",
                    gender = "neutral",
                ),
            )
        }

    /**
     * Текущий движок из настроек. Неизвестное или пустое значение читается как
     * системный TTS — так же, как это уже делает `pref_voice_engine`.
     *
     * При включённом «только голос телефона» ([OcrPreferences.voicePhoneOnly])
     * ответ системный — но только если читатель не выбрал сетевой движок
     * осознанно. Явный выбор важнее умолчания, иначе выбранный онлайн-голос
     * не звучал бы вообще (см. [resolveSpeakEngine]).
     */
    fun current(prefs: OcrPreferences): VoicePluginDescriptor = resolvePlugin(
        engineId = prefs.voiceEngine().get(),
        phoneOnly = runCatching { prefs.voicePhoneOnly().get() }.getOrDefault(true),
    )

    /**
     * Выбор движка без чтения настроек — чтобы правило «только голос телефона»
     * проверялось тестом, а не только глазами.
     */
    internal fun resolvePlugin(engineId: String?, phoneOnly: Boolean): VoicePluginDescriptor =
        if (phoneOnly && !isOnlineEngineId(engineId)) SYSTEM_TTS else byId(engineId) ?: SYSTEM_TTS

    /**
     * Сетевые id движков, которые читатель выбирает осознанно.
     *
     * Важно: «только голос телефона» отменяет АВТОМАТИЧЕСКИЙ сетевой маршрут
     * (`system_tts`/`auto`), но не явный выбор. Иначе выбранный онлайн-голос
     * молча уходил в системный движок, а тот его не имеет, и чтение требовало
     * «установите TTS» вместо воспроизведения выбранного голоса.
     */
    internal fun isOnlineEngineId(engineId: String?): Boolean =
        engineId != null && engineId in ONLINE_ENGINE_IDS

    internal val ONLINE_ENGINE_IDS = setOf(
        TtsSpeaker.ENGINE_GOOGLE_WEB,
        TtsSpeaker.ENGINE_EDGE_TTS,
        TtsSpeaker.ENGINE_ELEVENLABS,
    )

    /**
     * Движок для синтеза: учитывает сеть и «только голос телефона».
     *
     * @param online доступна ли сеть; без неё сетевой движок не используется.
     */
    internal fun resolveSpeakEngine(engineId: String?, phoneOnly: Boolean, online: Boolean): String {
        val explicitOnline = isOnlineEngineId(engineId)
        val resolved = when {
            // Неизвестный или пустой id — читаем системным голосом. Раньше
            // мусорный id уходил в TtsSpeaker как есть, и тот искал голос
            // несуществующего движка вместо того, чтобы просто заговорить.
            engineId == null -> TtsSpeaker.ENGINE_SYSTEM
            engineId == TtsSpeaker.ENGINE_AUTO -> if (online) TtsSpeaker.ENGINE_GOOGLE_WEB else TtsSpeaker.ENGINE_SYSTEM
            explicitOnline -> if (online) engineId else TtsSpeaker.ENGINE_SYSTEM
            else -> byId(engineId)?.id ?: TtsSpeaker.ENGINE_SYSTEM
        }
        return if (phoneOnly && !explicitOnline) TtsSpeaker.ENGINE_SYSTEM else resolved
    }

    /**
     * Сохранённые пресеты голосов. Список намеренно короткий: полный перечень
     * голосов устройства требует живой `TextToSpeech` (см. [systemVoices]), а
     * реестр вызывается прямо из Compose и не должен блокировать UI.
     */
    fun systemVoiceSources(prefs: OcrPreferences): List<Voice> = listOfNotNull(
        prefs.voiceFemale().get().takeIf(String::isNotBlank)?.let {
            Voice(id = it, name = "Женский пресет", gender = "female")
        },
        prefs.voiceMale().get().takeIf(String::isNotBlank)?.let {
            Voice(id = it, name = "Мужской пресет", gender = "male")
        },
        prefs.voiceName().get().takeIf(String::isNotBlank)?.let {
            Voice(id = it, name = "Выбранный голос", gender = "neutral")
        },
    ).distinctBy { it.id }

    /**
     * Все Android TTS-движки устройства: пакет → имя. Пустой id — «движок по
     * умолчанию системы».
     *
     * Это и есть «голоса из APK»: любой установленный сторонний TTS-движок
     * является отдельным приложением и виден здесь. Список идёт в
     * `pref_system_tts_engine`, а не в `pref_voice_name`: движок и голос внутри
     * движка — разные настройки, и их смешение ломало бы выбор голоса.
     *
     * Здесь намеренно НЕ используется `TtsSpeaker.installedEngines()`: вторая
     * половина того метода до трёх секунд ждёт `onInit` на `CountDownLatch`, а
     * реестр вызывается из Compose. `queryIntentServices` отдаёт тот же список
     * пакетов мгновенно и без инициализации движка.
     */
    fun systemEngineOptions(
        context: Context,
        prefs: OcrPreferences,
        defaultLabel: String,
    ): List<Pair<String, String>> {
        val engines = installedSystemEngines(context)
        val selected = runCatching { prefs.systemTtsEngine().get().trim() }.getOrDefault("")
        val fallback = selected
            .takeIf { it.isNotBlank() && engines.none { (pkg, _) -> pkg == selected } }
            ?.let { pkg -> listOf(pkg to "Выбранный движок ($pkg)") }
            .orEmpty()
        return listOf("" to defaultLabel) + engines + fallback
    }

    /**
     * Android TTS-движки, установленные в системе: пакет → человекочитаемое имя.
     */
    fun installedSystemEngines(context: Context): List<Pair<String, String>> {
        val app = context.applicationContext
        return runCatching {
            val pm = app.packageManager
            val intent = Intent(TextToSpeech.Engine.INTENT_ACTION_TTS_SERVICE)
            val services = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
                pm.queryIntentServices(intent, PackageManager.ResolveInfoFlags.of(0L))
            } else {
                @Suppress("DEPRECATION")
                pm.queryIntentServices(intent, 0)
            }
            val found = LinkedHashMap<String, String>()
            services.forEach { info ->
                val pkg = info.serviceInfo?.packageName ?: return@forEach
                val label = runCatching { info.serviceInfo.loadLabel(pm).toString() }
                    .getOrNull()
                    ?.takeIf { it.isNotBlank() }
                    ?: pkg
                found.putIfAbsent(pkg, label)
            }
            found.toList()
        }.onFailure { error ->
            logcat(LogPriority.WARN, error) { "Не удалось перечислить системные TTS-движки" }
        }.getOrDefault(emptyList())
    }

    /**
     * Голоса конкретного системного движка по языку. Тяжёлая операция: нужен
     * живой `TextToSpeech`, поэтому вызывается из корутины, а не из Compose.
     */
    suspend fun systemVoices(
        context: Context,
        enginePackage: String?,
        language: String,
    ): List<Voice> = withContext(Dispatchers.IO) {
        val tts = runCatching {
            TextToSpeech(
                context.applicationContext,
                {},
                enginePackage?.takeIf { it.isNotBlank() },
            )
        }.getOrNull() ?: return@withContext emptyList()
        try {
            VoiceHelper.prepareForLanguage(tts, language)
            VoiceHelper.voicesFor(tts, language, enginePackage).map { voice ->
                Voice(
                    id = voice.name,
                    name = voice.name,
                    gender = when (VoiceHelper.classify(voice)) {
                        VoiceKind.FEMALE -> "female"
                        VoiceKind.MALE -> "male"
                        else -> "neutral"
                    },
                    language = runCatching { voice.locale.toLanguageTag() }.getOrNull(),
                    installed = true,
                )
            }
        } finally {
            runCatching { tts.shutdown() }
        }
    }
}

