import java.net.HttpURLConnection
import java.net.URL
import java.security.MessageDigest
import java.util.GregorianCalendar
import java.util.Locale
import java.util.TimeZone
import java.util.UUID
import java.util.concurrent.TimeUnit
import kotlin.coroutines.resume

/**
 * Клиент бесплатной онлайн-озвучки Microsoft Edge (edge-tts): те же WebSocket-
 * endpoint и голоса, что использует «Читать вслух» в браузере Edge.
 *
 * Никакого API-ключа не требуется — только интернет. Голоса отдаются
 * аудио-потоком MP3, который приложение проигрывает тем же плеером, что и
 * остальные сетевые движки (Google Web, ElevenLabs).
 *
 * Протокол (раньше жил в Python-библиотеке rany2/edge-tts):
 *  - список голосов — GET voices/list (парсится строками без библиотек);
 *  - синтез — WebSocket wss://speech.platform.bing.com/.../edge/v1, на вход
 *    speech.config + SSML, на выход бинарные сообщения с MP3-чанками.
 *  - Sec-MS-GEC — SHA-256 от (Unix-время в тиках Windows 1601, округлённое
 *    до 5 минут) + trusted-токен; иначе сервер закрывает соединение.
 *
 * Мультиязычные голоса (ShortName содержит «Multilingual») распознают язык
 * текста автоматически — они отмечены в списке и доступны для любого текста.
 */
object EdgeTts {

    private const val TRUSTED_CLIENT_TOKEN = "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
    /** Разница эпох Unix (1970) и Windows file time (1601), в секундах. */
    private const val WIN_EPOCH = 11_644_473_600L
    private const val CHROMIUM_FULL_VERSION = "143.0.3650.75"
    private const val CHROMIUM_MAJOR = "143"
    private const val SEC_MS_GEC_VERSION = "1-$CHROMIUM_FULL_VERSION"

    private const val BASE_URL =
        "speech.platform.bing.com/consumer/speech/synthesize/readaloud"
    private const val VOICE_LIST_URL =
        "https://$BASE_URL/voices/list?trustedclienttoken=$TRUSTED_CLIENT_TOKEN"
    private const val WSS_URL =
        "wss://$BASE_URL/edge/v1?TrustedClientToken=$TRUSTED_CLIENT_TOKEN"

    /** Голос по умолчанию: русский женский (нейтральный). */
    const val DEFAULT_VOICE = "ru-RU-SvetlanaNeural"

    private const val SSML_BYTE_LIMIT = 3600
    private const val AUDIO_CACHE_FILES = 32
    private const val AUDIO_CACHE_BYTES = 64L * 1024L * 1024L

    private val client by lazy {
        OkHttpClient.Builder()
            .connectTimeout(15, TimeUnit.SECONDS)
            .readTimeout(90, TimeUnit.SECONDS)
            .pingInterval(10, TimeUnit.SECONDS)
            .build()
    }

    private val userAgent =
        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 " +
            "(KHTML, like Gecko) Chrome/$CHROMIUM_MAJOR.0.0.0 Safari/537.36 " +
            "Edg/$CHROMIUM_MAJOR.0.0.0"

    /** Один голос Edge TTS из публичного списка. */
    data class EdgeVoice(
        val shortName: String,
        val gender: String,
        val locale: String,
        val friendlyName: String,
    ) {
        /** Мультиязычные голоса понимают ЖД текст на любом из больших языков. */
        val multilingual: Boolean get() = shortName.contains("Multilingual", ignoreCase = true)
        val language: String get() = locale.substringBefore('-').lowercase()
        val genderIcon: String get() = when {
            gender.contains("Female", true) -> "♀"
            gender.contains("Male", true) -> "♂"
            else -> "•"
        }
        /** Короткая подпись для списка: название • пол • язык (+ 🌐). */
        val label: String
            get() = buildString {
                append(shortName)
                append(" • ").append(genderIcon)
                append(" ").append(locale)
                if (multilingual) append(" • 🌐 мультиязычный")
            }
    }

    /** Все доступные языки в полученном списке голосов, отсортированы (ru первым). */
    fun languagesOf(voices: List<EdgeVoice>): List<String> = voices
        .map { it.language }
        .distinct()
        .sortedWith(compareBy<String> { it != "ru" }.thenBy { it })

    /** Мультиязычные голоса (понимают любой текст из основных языков). */
    fun multilingualVoices(voices: List<EdgeVoice>): List<EdgeVoice> =
        voices.filter { it.multilingual }

    /**
     * Sec-MS-GEC токен: SHA-256 от (Windows-file-time, округлённый до 5 минут)
     * + trusted-токен. Без него сервер отвечает 403/закрывает вебсокет.
     */
    fun secMsGec(nowEpochSeconds: Long = System.currentTimeMillis() / 1000): String {
        var ticks = nowEpochSeconds + WIN_EPOCH
        ticks -= ticks % 300L
        val windowsTicks = ticks * 10_000_000L
        val digest = MessageDigest.getInstance("SHA-256")
            .digest("$windowsTicks$TRUSTED_CLIENT_TOKEN".toByteArray(Charsets.US_ASCII))
        return digest.joinToString("") { "%02X".format(it.toInt() and 0xFF) }
    }

    /** «Javascript-стиль» дата-строка, которую ждёт сервер в X-Timestamp. */
    private fun jsTimestamp(): String {
        val cal = GregorianCalendar(TimeZone.getTimeZone("UTC"))
        val days = arrayOf("Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat")
        val months = arrayOf("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
        return String.format(
            Locale.US,
            "%s %s %02d %04d %02d:%02d:%02d GMT+0000 (Coordinated Universal Time)",
            days[cal.get(GregorianCalendar.DAY_OF_WEEK) - 1],
            months[cal.get(GregorianCalendar.MONTH)],
            cal.get(GregorianCalendar.DAY_OF_MONTH),
            cal.get(GregorianCalendar.YEAR),
            cal.get(GregorianCalendar.HOUR_OF_DAY),
            cal.get(GregorianCalendar.MINUTE),
            cal.get(GregorianCalendar.SECOND),
        )
    }

    private fun uuidHex(): String = UUID.randomUUID().toString().replace("-", "")

    private fun escapeXml(s: String): String = buildString {
        for (c in s) {
            when (c) {
                '&' -> append("&amp;")
                '<' -> append("&lt;")
                '>' -> append("&gt;")
                '"' -> append("&quot;")
                '\'' -> append("&apos;")
                else -> append(c)
            }
        }
    }

    /**
     * Список ВСЕХ голосов Edge TTS (текущий каталог: ~300 голосов, 50+ языков).
     * Пустой список при ошибке сети/403 — никаких фейковых данных.
     */
    suspend fun fetchVoices(): List<EdgeVoice> = withContext(Dispatchers.IO) {
        runCatching {
            val conn = URL(VOICE_LIST_URL +
                "&Sec-MS-GEC=${secMsGec()}&Sec-MS-GEC-Version=$SEC_MS_GEC_VERSION")
                .openConnection() as HttpURLConnection
            conn.connectTimeout = 15_000
            conn.readTimeout = 30_000
            conn.setRequestProperty("User-Agent", userAgent)
            conn.setRequestProperty("Authority", "speech.platform.bing.com")
            conn.setRequestProperty("Accept", "*/*")
            conn.setRequestProperty("Sec-Fetch-Site", "none")
            conn.setRequestProperty("Sec-Fetch-Mode", "cors")
            conn.setRequestProperty("Sec-Fetch-Dest", "empty")
            conn.setRequestProperty("Sec-CH-UA-Mobile", "?0")
            if (conn.responseCode !in 200..299) {
                logcat(LogPriority.WARN) { "EdgeTTS voices HTTP ${conn.responseCode}" }
                return@runCatching emptyList<EdgeVoice>()
            }
            val body = conn.inputStream.bufferedReader().readText()
            conn.disconnect()
            val arr = org.json.JSONArray(body)
            buildList {
                for (i in 0 until arr.length()) {
                    val v = arr.optJSONObject(i) ?: continue
                    val short = v.optString("ShortName")
                    if (short.isBlank()) continue
                    val locale = v.optString("Locale").ifBlank { "xx-XX" }
                    add(
                        EdgeVoice(
                            shortName = short,
                            gender = v.optString("Gender"),
                            locale = locale,
                            friendlyName = v.optString("FriendlyName").ifBlank { short },
                        ),
                    )
                }
            }.sortedWith(
                compareBy(
                    { it.friendlyName.contains("Multilingual", true) },
                    { it.locale },
                    { it.shortName },
                ),
            )
        }.getOrElse { error ->
            logcat(LogPriority.WARN, error) { "EdgeTTS voice list fetch failed" }
            emptyList()
        }
    }

    /**
     * Синтез одного текста в файл MP3. [ratePercent] и [pitchHz] — значения
     * prosody от настроек скорости/высоты приложения (0 = обычный голос).
     * Вернёт null при ошибке сети/сервера/пустого результата.
     */
    suspend fun synthesizeToFile(
        context: Context,
        text: String,
        voice: String = DEFAULT_VOICE,
        ratePercent: Int = 0,
        pitchHz: Int = 0,
        useCache: Boolean = false,
    ): File? = withContext(Dispatchers.IO) {
        val cleanText = sanitizeForSsml(text)
        if (cleanText.isBlank()) return@withContext null
        val cacheDir = File(context.cacheDir, "edge_tts").apply { mkdirs() }
        val cached = audioCacheFile(cacheDir, cleanText, voice, ratePercent, pitchHz)
        if (useCache && cached.isFile && cached.length() >= 1024) return@withContext cached
        val target = if (useCache) {
            File.createTempFile("edge_", ".mp3", cacheDir)
        } else {
            File(context.cacheDir, "tts_edge_${System.nanoTime()}.mp3")
        }
        var completed = false
        try {
            target.outputStream().buffered().use { output ->
                for (chunk in chunkForSsml(cleanText)) {
                    val data = speakChunk(chunk, voice, ratePercent, pitchHz, 0)
                    if (data.isEmpty()) {
                        throw IllegalStateException("EdgeTTS returned an empty chunk for $voice")
                    }
                    output.write(data)
                }
            }
            if (!useCache) {
                completed = true
                target
            } else {
                if (!target.renameTo(cached)) {
                    target.copyTo(cached, overwrite = true)
                    target.delete()
                }
                pruneAudioCache(cacheDir)
                if (cached.length() < 1024) {
                    cached.delete()
                    null
                } else {
                    completed = true
                    cached
                }
            }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            logcat(LogPriority.WARN, e) { "EdgeTTS synthesis failed" }
            null
        } finally {
            if (!completed && target.exists()) target.delete()
        }
    }

    internal fun chunkForSsml(text: String, limit: Int = SSML_BYTE_LIMIT): List<String> {
        if (text.isBlank() || limit <= 0) return emptyList()
        val chunks = mutableListOf<String>()
        var start = 0
        while (start < text.length) {
            while (start < text.length && text[start].isWhitespace()) start++
            if (start >= text.length) break
            if (escapeXml(text.substring(start)).toByteArray(Charsets.UTF_8).size <= limit) {
                chunks += text.substring(start).trim()
                break
            }
            var low = start + 1
            var high = text.length
            var end = start
            while (low <= high) {
                val middle = (low + high) ushr 1
                val size = escapeXml(text.substring(start, middle)).toByteArray(Charsets.UTF_8).size
                if (size <= limit) {
                    end = middle
                    low = middle + 1
                } else {
                    high = middle - 1
                }
            }
            if (end <= start) end = (start + 1).coerceAtMost(text.length)
            val usefulStart = start + (end - start) * 3 / 4
            val whitespace = text.substring(usefulStart, end).lastIndexOfAny(charArrayOf(' ', '\n', '\r', '\t'))
            val cut = if (whitespace >= 0) usefulStart + whitespace + 1 else end
            chunks += text.substring(start, cut).trim()
            start = cut
        }
        return chunks.filter(String::isNotBlank)
    }

    private fun sanitizeForSsml(text: String): String = buildString(text.length) {
        for (char in text) {
            when {
                char == '\n' || char == '\r' || char == '\t' -> append(char)
                char.code in 0..31 || char.code in 127..159 -> Unit
                else -> append(char)
            }
        }
    }.replace("\r\n", "\n").replace('\r', '\n').trim()

    private fun audioCacheFile(
        directory: File,
        text: String,
        voice: String,
        ratePercent: Int,
        pitchHz: Int,
    ): File {
        val source = "$voice|$ratePercent|$pitchHz|$text"
        val digest = MessageDigest.getInstance("SHA-256")
            .digest(source.toByteArray(Charsets.UTF_8))
            .joinToString("") { "%02x".format(it.toInt() and 0xFF) }
        return File(directory, "$digest.mp3")
    }

    private fun pruneAudioCache(directory: File) {
        val files = directory.listFiles { file -> file.isFile && file.extension.equals("mp3", true) }
            ?.sortedBy { it.lastModified() }
            .orEmpty()
        var totalBytes = files.sumOf(File::length)
        var remaining = files.size
        for (file in files) {
            if (remaining <= AUDIO_CACHE_FILES && totalBytes <= AUDIO_CACHE_BYTES) break
            val size = file.length()
            if (file.delete()) {
                totalBytes -= size
                remaining--
            }
        }
    }

    /** Один SSML-запрос на WebSocket, возвращает конкатенированный MP3. */
    private suspend fun speakChunk(
        text: String,
        voice: String,
        ratePercent: Int,
        pitchHz: Int,
        volumePercent: Int,
    ): ByteArray = suspendCancellableCoroutine { cont ->
            val requestId = uuidHex()
            val url = WSS_URL +
                "&Sec-MS-GEC=${secMsGec()}" +
                "&Sec-MS-GEC-Version=$SEC_MS_GEC_VERSION" +
                "&ConnectionId=$requestId"
            val request = Request.Builder()
                .url(url)
                .header("User-Agent", userAgent)
                .header("Pragma", "no-cache")
                .header("Cache-Control", "no-cache")
                .header("Origin", "chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold")
                .header("Sec-WebSocket-Version", "13")
                .header("Cookie", "muid=${uuidHex().uppercase()};")
                .build()
            val ws = client.newWebSocket(request, EdgeSocketListener(
                requestId = requestId,
                voice = voice,
                text = text,
                ratePercent = ratePercent,
                pitchHz = pitchHz,
                volumePercent = volumePercent,
                onResult = { bytes -> if (cont.isActive) cont.resume(bytes) },
                onError = { error ->
                    if (cont.isActive) cont.resume(ByteArray(0))
                    if (error != null) logcat(LogPriority.WARN, error) { "EdgeTTS websocket error" }
                },
            ))
            cont.invokeOnCancellation { ws.cancel() }
        }

    /** Собирает MP3 из бинарных аудио-сообщений WebSocket-соединения. */
    private class EdgeSocketListener(
        private val requestId: String,
        private val voice: String,
        private val text: String,
        private val ratePercent: Int,
        private val pitchHz: Int,
        private val volumePercent: Int,
        private val onResult: (ByteArray) -> Unit,
        private val onError: (Throwable?) -> Unit,
    ) : WebSocketListener() {

        private val audio = java.io.ByteArrayOutputStream()
        private var finished = false

        override fun onOpen(webSocket: WebSocket, response: Response) {
            val ts = jsTimestamp()
            webSocket.send(
                "X-Timestamp:$ts\r\n" +
                    "Content-Type:application/json; charset=utf-8\r\n" +
                    "Path:speech.config\r\n\r\n" +
                    "{\"context\":{\"synthesis\":{\"audio\":{\"metadataoptions\":" +
                    "{\"sentenceBoundaryEnabled\":\"false\",\"wordBoundaryEnabled\":\"true\"}," +
                    "\"outputFormat\":\"audio-24khz-48kbitrate-mono-mp3\"}}}}\r\n",
            )
            val s = escapeXml(text)
            val rate = if (ratePercent >= 0) "+$ratePercent%" else "$ratePercent%"
            val pitch = if (pitchHz >= 0) "+${pitchHz}Hz" else "${pitchHz}Hz"
            val vol = if (volumePercent >= 0) "+$volumePercent%" else "$volumePercent%"
            val language = voice.substringBefore('-', "en").lowercase(Locale.US)
            val ssml =
                "<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' " +
                    "xml:lang='$language'><voice name='${escapeXml(voice)}'>" +
                    "<prosody pitch='$pitch' rate='$rate' volume='$vol'>$s</prosody>" +
                    "</voice></speak>"
            webSocket.send(
                "X-RequestId:$requestId\r\n" +
                    "Content-Type:application/ssml+xml\r\n" +
                    "X-Timestamp:${ts}Z\r\n" +
                    "Path:ssml\r\n\r\n$ssml",
            )
        }

        override fun onMessage(webSocket: WebSocket, text: String) {
            // Path:turn.end — конец аудио для этого запроса.
            if (text.contains("turn.end")) finish(webSocket)
        }

        override fun onMessage(webSocket: WebSocket, bytes: ByteString) {
            val n = bytes.size
            if (n < 2) return
            val headerLength = ((bytes[0].toInt() and 0xFF) shl 8) or (bytes[1].toInt() and 0xFF)
            if (2 + headerLength > n) return
            val header = bytes.substring(2, 2 + headerLength).utf8()
            if (header.contains("Path:audio", ignoreCase = true) &&
                header.contains("Content-Type:audio/mpeg", ignoreCase = true)
            ) {
                // Аудио идёт сразу после заголовка + \r\n\r\n (2 байта).
                val data = bytes.substring(2 + headerLength)
                if (data.size > 0) audio.write(data.toByteArray())
            }
        }

        override fun onClosed(webSocket: WebSocket, code: Int, reason: String) {
            if (!finished) {
                finished = true
                onError(null)
            }
        }

        override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
            if (!finished) {
                finished = true
                onError(t)
            }
        }

        private fun finish(webSocket: WebSocket) {
            if (finished) return
            finished = true
            runCatching { webSocket.close(1000, "ok") }
            onResult(audio.toByteArray())
        }
    }
}

package eu.kanade.tachiyomi.data.tts

/**
 * Разметка реплик для озвучки.
 *
 * На экране у каждой реплики есть служебные пометки — номер по порядку
 * чтения, кто говорит, пауза. Их должно быть ВИДНО, но TTS не должен их
 * произносить. Поэтому текст для показа и текст для синтеза расходятся:
 * [strip] снимает разметку перед отправкой в движок.
 *
 * Поддерживаемые пометки:
 *
 * | Запись        | Значение                                   | Читается |
 * |---------------|--------------------------------------------|----------|
 * | `{1}`         | номер реплики в порядке чтения             | нет      |
 * | `{ж}` `{м}`   | пол говорящего (женский / мужской)         | нет      |
 * | `{ж2}`        | вторая женщина в сцене (свой голос)        | нет      |
 * | `{имя:Аки}`   | имя говорящего                             | нет      |
 * | `{пауза}`     | дополнительная пауза перед репликой        | нет      |
 * | `{...}`       | любая другая служебная пометка             | нет      |
 * | `÷`           | разделитель частей реплики (короткая пауза)| нет      |
 *
 * Всё, что не в фигурных скобках, читается как обычно.
 */
object SpeechMarkup {

    // ВАЖНО: фигурные скобки внутри класса символов обязаны быть экранированы.
    // На JVM/ART без экрана работает и без экрана, но ICU-движок регулярок
    // (Itel, Infinix и др. Android 13+) бросает PatternSyntaxException прямо в
    // <clinit>, из-за чего ЛЮБОЕ обращение к TTS роняло приложение
    // (ExceptionInInitializerError).
    private val TAG = Regex("""\{[^\{\}]{0,40}\}""")
    private val DIVIDER = '÷'

    /** Пол, объявленный разметкой: "female" | "male" | null. */
    fun genderOf(text: String): String? {
        val m = TAG.findAll(text).map { it.value.trim('{', '}').lowercase() }
        m.forEach {
            when {
                it.startsWith("ж") || it.startsWith("f") -> return "female"
                it.startsWith("м") || it.startsWith("m") -> return "male"
            }
        }
        return null
    }

    /**
     * Номер говорящего в сцене: `{ж2}` -> 1 (второй женский слот),
     * `{ж}`/`{м}` -> 0. Нужен, чтобы два персонажа одного пола звучали
     * разными голосами.
     */
    fun speakerSlot(text: String): Int {
        TAG.findAll(text).forEach { match ->
            val body = match.value.trim('{', '}').lowercase()
            if (body.startsWith("ж") || body.startsWith("м") ||
                body.startsWith("f") || body.startsWith("m")
            ) {
                val digits = body.dropWhile { !it.isDigit() }.takeWhile { it.isDigit() }
                if (digits.isNotEmpty()) return (digits.toIntOrNull() ?: 1).minus(1).coerceAtLeast(0)
                return 0
            }
        }
        return 0
    }

    /** Есть ли запрос на дополнительную паузу перед репликой. */
    fun hasPause(text: String): Boolean =
        TAG.findAll(text).any { it.value.trim('{', '}').lowercase().startsWith("пауза") }

    /** Имя говорящего из `{имя:Аки}`, если задано. */
    fun speakerName(text: String): String? {
        TAG.findAll(text).forEach { match ->
            val body = match.value.trim('{', '}')
            val lower = body.lowercase()
            if (lower.startsWith("имя:") || lower.startsWith("name:")) {
                return body.substringAfter(':').trim().ifBlank { null }
            }
        }
        return null
    }

    /**
     * Текст для синтеза: разметка убрана, `÷` заменён на запятую (короткая
     * пауза), лишние пробелы схлопнуты.
     */
    fun strip(text: String): String {
        var out = TAG.replace(text, " ")
        out = out.replace(DIVIDER, ',')
        out = out.replace(Regex("[~≈]+"), "") // тильду не озвучивать словом «тильда»
        out = out.replace(Regex("""\s+"""), " ")
        out = out.replace(Regex("""\s+([,.!?;:])"""), "$1")
        out = out.replace(Regex(""",{2,}"""), ",")
        return out.trim().trim(',').trim()
    }

    fun forSpeech(text: String): String {
        var out = text.replace(Regex("\\.{2,}"), "…")
        out = out.replace(Regex("!{2,}"), "!!")
        out = out.replace(Regex("\\?{2,}"), "??")
        out = out.replace(Regex("([!?]{2})[!?]+"), "$1")
        out = out.replace(Regex("(?:;;|:){2,}"), ";")
        out = out.replace(Regex("\\s+([,!?;:…])"), "$1")
        out = out.replace(Regex("(^|\\s)[.,!?;:·•*#|/^_=+<>]+(\\s|$)"), " ")
        out = out.replace(Regex(",{2,}"), ",")
        out = out.replace(Regex("\\s{2,}"), " ")
        return out.trim().trim(',').trim()
    }

    /** Добавляет номер реплики в начало, если его там ещё нет. */
    fun withIndex(text: String, index: Int): String =
        if (TAG.containsMatchIn(text) && text.trimStart().startsWith("{$index}")) {
            text
